  ('samfunnsfag-9:kamp-for-endring', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-9:forste-verdenskrig', 'samfunnsfag-9', 'forste-verdenskrig', 'Første verdenskrig', 'Årsakene til og konsekvensene av første verdenskrig, hvordan krigen ble ført, hvordan Norge ble rammet, og om krigen kunne vært unngått.', array[7]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-9:forste-verdenskrig', '## En verdenskrig
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-9:forste-verdenskrig', 'Første verdenskrig', 'Krigen mellom stormaktene i Europa fra 1914 til 1918.', 0),
  ('samfunnsfag-9:forste-verdenskrig', 'Sentralmaktene', 'Tyskland og Østerrike-Ungarn, senere også Det osmanske riket og Bulgaria.', 1),
  ('samfunnsfag-9:forste-verdenskrig', 'Ententemaktene', 'Storbritannia, Frankrike og Russland, senere også blant annet Italia og USA.', 2),
  ('samfunnsfag-9:forste-verdenskrig', 'Militarisme', 'At militærmakt og opprustning får stor plass i et samfunn.', 3),
  ('samfunnsfag-9:forste-verdenskrig', 'Imperialisme', 'Stormaktenes kappløp om kolonier og innflytelse.', 4),
  ('samfunnsfag-9:forste-verdenskrig', 'Nasjonalisme', 'Sterk stolthet over og lojalitet til egen nasjon.', 5),
  ('samfunnsfag-9:forste-verdenskrig', 'Skuddene i Sarajevo', 'Drapet på tronfølgeren Franz Ferdinand 28. juni 1914, den utløsende årsaken.', 6),
  ('samfunnsfag-9:forste-verdenskrig', 'Utløsende årsak', 'Hendelsen som setter i gang en konflikt som har langsiktige årsaker.', 7),
  ('samfunnsfag-9:forste-verdenskrig', 'Skyttergravskrig', 'Krig der soldatene lå i gravde grøfter overfor hverandre i lang tid.', 8),
  ('samfunnsfag-9:forste-verdenskrig', 'Verdun og Somme', 'Store slag på vestfronten i 1916 med enorme tap.', 9),
  ('samfunnsfag-9:forste-verdenskrig', 'Nye våpen', 'Maskingevær, giftgass, stridsvogner, fly og ubåter.', 10),
  ('samfunnsfag-9:forste-verdenskrig', 'Våpenhvilen', 'Kampene stanset 11. november 1918.', 11),
  ('samfunnsfag-9:forste-verdenskrig', 'Versaillestraktaten', 'Fredsavtalen fra 1919 som ga Tyskland skylden og store krigserstatninger.', 12),
  ('samfunnsfag-9:forste-verdenskrig', 'Folkeforbundet', 'Internasjonal organisasjon fra 1920 som skulle sikre fred.', 13),
  ('samfunnsfag-9:forste-verdenskrig', 'Nøytralitet', 'At et land ikke tar side i en krig, slik Norge gjorde.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-9:forste-verdenskrig', 'q01', 'flervalg', 'Når varte første verdenskrig?', array['1905–1910', '1914–1918', '1939–1945', '1918–1922']::text[], 1, 'Krigen startet sommeren 1914 og endte med våpenhvilen i november 1918.', true, true, 0),
  ('samfunnsfag-9:forste-verdenskrig', 'q02', 'flervalg', 'Hva var den utløsende årsaken til krigen?', array['Skuddene i Sarajevo i 1914', 'Den russiske revolusjonen', 'Versaillestraktaten', 'Angrepet på Pearl Harbor']::text[], 0, 'Drapet på Franz Ferdinand satte i gang en kjedereaksjon.', true, true, 1),
  ('samfunnsfag-9:forste-verdenskrig', 'q03', 'flervalg', 'Hvilke land var ententemaktene ved krigens start?', array['Tyskland og Østerrike-Ungarn', 'USA, Japan og Kina', 'Storbritannia, Frankrike og Russland', 'Norge, Sverige og Danmark']::text[], 2, 'Ententemaktene sto mot sentralmaktene.', true, true, 2),
  ('samfunnsfag-9:forste-verdenskrig', 'q04', 'flervalg', 'Hva kjennetegnet krigen på vestfronten?', array['Raske angrep med fly', 'Krig til sjøs', 'Kamper i jungelen', 'Skyttergravskrig med store tap for små landområder']::text[], 3, 'Fronten flyttet seg lite i nesten fire år.', true, true, 3),
  ('samfunnsfag-9:forste-verdenskrig', 'q05', 'flervalg', 'Hva var imperialisme?', array['Kappløp mellom stormaktene om kolonier og innflytelse', 'Kjærlighet til eget land', 'Oppbygging av hærer', 'Samarbeid mellom land']::text[], 0, 'Rivaliseringen om kolonier skapte spenninger mellom stormaktene.', true, true, 4),
  ('samfunnsfag-9:forste-verdenskrig', 'q06', 'flervalg', 'Hvorfor ble krigen raskt en storkrig mellom mange land?', array['Fordi alle ønsket krig', 'Fordi alliansene dro stormaktene inn i konflikten', 'Fordi Norge angrep Tyskland', 'Fordi USA startet krigen']::text[], 1, 'Landene hadde lovet å hjelpe hverandre, og konflikten spredte seg på få dager.', true, true, 5),
  ('samfunnsfag-9:forste-verdenskrig', 'q07', 'flervalg', 'Hvilket land fikk skylden for krigen i Versaillestraktaten?', array['Russland', 'Frankrike', 'Serbia', 'Tyskland']::text[], 3, 'Skyldparagrafen skapte bitterhet i Tyskland.', true, true, 6),
  ('samfunnsfag-9:forste-verdenskrig', 'q08', 'flervalg', 'Hvordan ble Norge rammet, selv om landet var nøytralt?', array['Norge ble okkupert', 'Mange norske handelsskip ble senket', 'Norske soldater kjempet i Frankrike', 'Kristiania ble bombet']::text[], 1, 'Om lag 2000 norske sjøfolk omkom.', true, true, 7),
  ('samfunnsfag-9:forste-verdenskrig', 'q09', 'flervalg', 'Hvilken organisasjon ble opprettet etter krigen for å sikre fred?', array['FN', 'NATO', 'Folkeforbundet', 'EU']::text[], 2, 'Folkeforbundet klarte likevel ikke å hindre en ny verdenskrig.', true, false, 8),
  ('samfunnsfag-9:forste-verdenskrig', 'q10', 'flervalg', 'Hvilket spørsmål er et eksempel på å reflektere over om krigen kunne vært hindret?', array['Hvor mange soldater deltok?', 'Hvem vant slaget ved Verdun?', 'Hva het den østerrikske tronfølgeren?', 'Hva om alliansene hadde vært mindre bindende?']::text[], 3, 'Å endre én forutsetning i tanken hjelper oss å se hvilke årsaker som var viktigst.', true, false, 9),
  ('samfunnsfag-9:forste-verdenskrig', 'm01', 'sant-usant', 'USA gikk inn i krigen i 1917.', array['Sant', 'Usant']::text[], 0, 'Blant annet den tyske ubåtkrigen fikk USA til å gå inn på ententens side.', false, true, 10),
  ('samfunnsfag-9:forste-verdenskrig', 'm02', 'sant-usant', 'Krigen endte med en våpenhvile 11. november 1918.', array['Sant', 'Usant']::text[], 0, 'Fredsavtalen, Versaillestraktaten, kom året etter.', false, true, 11),
  ('samfunnsfag-9:forste-verdenskrig', 'm03', 'sant-usant', 'Østerrike-Ungarn ble styrket etter krigen.', array['Sant', 'Usant']::text[], 1, 'Riket gikk i oppløsning, og flere nye stater ble opprettet.', false, true, 12),
  ('samfunnsfag-9:forste-verdenskrig', 'm04', 'sant-usant', 'Norge kjempet på sentralmaktenes side.', array['Sant', 'Usant']::text[], 1, 'Norge var nøytralt under hele krigen.', false, true, 13),
  ('samfunnsfag-9:forste-verdenskrig', 'm05', 'flervalg', 'Hvilket nytt våpen ble tatt i bruk under første verdenskrig?', array['Atombomben', 'Giftgass', 'Kanonen', 'Armbrøsten']::text[], 1, 'Giftgass skadet og drepte mange soldater i skyttergravene.', false, true, 14),
  ('samfunnsfag-9:forste-verdenskrig', 'm06', 'flervalg', 'Hva betyr nasjonalisme?', array['Sterk stolthet over og lojalitet til egen nasjon', 'Kappløp om kolonier', 'Å ha store hærer', 'Samarbeid mellom land']::text[], 0, 'Nasjonalisme skapte spenninger, særlig på Balkan.', false, true, 15),
  ('samfunnsfag-9:forste-verdenskrig', 'm07', 'flervalg', 'Hvilken stat ble opprettet etter første verdenskrig?', array['Tyskland', 'Frankrike', 'Polen', 'Storbritannia']::text[], 2, 'Polen ble igjen en selvstendig stat i 1918.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-9:forste-verdenskrig', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'samfunnsfag-9', 'mellomkrigstid-og-andre-verdenskrig', 'Mellomkrigstiden og andre verdenskrig', 'Hvordan økonomisk krise og diktaturer førte til andre verdenskrig, hovedtrekkene i krigen, okkupasjonen av Norge og konsekvensene etter 1945.', array[7, 8]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', '## Mellomkrigstiden
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'Mellomkrigstiden', 'Perioden mellom første og andre verdenskrig, 1918–1939.', 0),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'Børskrakket', 'Kraftig fall i aksjekursene i New York i 1929.', 1),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'Den store depresjonen', 'Verdensomspennende økonomisk krise på 1930-tallet med massearbeidsløshet.', 2),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'Fascisme', 'Ideologi med én sterk leder, ett parti og en aggressiv nasjonalisme. Mussolini i Italia.', 3),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'Nazisme', 'Hitlers ideologi, bygd på rasisme, antisemittisme og diktatur.', 4),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'Antisemittisme', 'Hat og fordommer mot jøder.', 5),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'Ettergivenhetspolitikk', 'Storbritannias og Frankrikes politikk med å gi etter for Hitlers krav for å unngå krig.', 6),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'Lynkrig', 'Raske angrep med fly, stridsvogner og soldater samtidig.', 7),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', '9. april 1940', 'Tyskland angrep Norge.', 8),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'Vidkun Quisling', 'Leder av Nasjonal Samling, som styrte Norge sammen med tyskerne.', 9),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'Motstandskampen', 'Nordmenn som kjempet mot okkupasjonen, for eksempel med sabotasje.', 10),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'Stalingrad', 'Slaget 1942–1943 som ble et vendepunkt på østfronten.', 11),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'D-dagen', '6. juni 1944, da de allierte gikk i land i Normandie.', 12),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', '8. mai 1945', 'Tyskland kapitulerte, og Norge ble fritt.', 13),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'FN', 'De forente nasjoner, opprettet i 1945 for å sikre fred og samarbeid.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'q01', 'flervalg', 'Hva utløste den store depresjonen?', array['Børskrakket i New York i 1929', 'Første verdenskrig', 'Angrepet på Polen', 'Den russiske revolusjonen']::text[], 0, 'Krakket spredte seg til økonomien i store deler av verden.', true, true, 0),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'q02', 'flervalg', 'Når ble Hitler rikskansler i Tyskland?', array['1919', '1929', '1939', '1933']::text[], 3, 'Kort tid etter avskaffet nazistene demokratiet.', true, true, 1),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'q03', 'flervalg', 'Hva var ettergivenhetspolitikken?', array['At Tyskland ga fra seg land', 'At Storbritannia og Frankrike ga etter for Hitlers krav for å unngå krig', 'At USA gikk inn i krigen', 'At Norge var nøytralt']::text[], 1, 'Håpet var at Hitler ville bli fornøyd, men han krevde stadig mer.', true, true, 2),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'q04', 'flervalg', 'Hvilken hendelse regnes som starten på andre verdenskrig?', array['Angrepet på Pearl Harbor', 'D-dagen', 'Tysklands angrep på Polen 1. september 1939', 'Børskrakket']::text[], 2, 'To dager senere erklærte Storbritannia og Frankrike krig mot Tyskland.', true, true, 3),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'q05', 'flervalg', 'Når angrep Tyskland Norge?', array['9. april 1940', '8. mai 1945', '1. september 1939', '17. mai 1940']::text[], 0, 'Etter to måneder med kamper var hele landet okkupert.', true, true, 4),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'q06', 'flervalg', 'Hvorfor fikk ekstreme ideologier oppslutning i mellomkrigstiden?', array['Fordi alle var fornøyde', 'Fordi økonomisk krise og misnøye fikk mange til å søke sterke ledere', 'Fordi demokratiet var forbudt i hele Europa', 'Fordi Folkeforbundet støttet dem']::text[], 1, 'Arbeidsløshet og nasjonal bitterhet ga grobunn for ekstreme løsninger.', true, true, 5),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'q07', 'flervalg', 'Hvilket slag regnes som et vendepunkt på østfronten?', array['Slaget ved Verdun', 'Slaget om Storbritannia', 'D-dagen', 'Slaget om Stalingrad']::text[], 3, 'Etter Stalingrad var det Sovjetunionen som rykket fram.', true, true, 6),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'q08', 'flervalg', 'Hva var sabotasjen på Vemork rettet mot?', array['En våpenfabrikk i Oslo', 'Produksjonen av tungtvann', 'En tysk ubåt', 'Bergensbanen']::text[], 1, 'Tungtvann kunne brukes i tysk atomforskning.', true, true, 7),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'q09', 'flervalg', 'Hva skjedde 8. mai 1945?', array['Japan angrep USA', 'Hitler kom til makten', 'Tyskland kapitulerte, og Norge ble fritt', 'FN ble opprettet']::text[], 2, 'Dagen er i dag frigjøringsdag i Norge.', true, false, 8),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'q10', 'flervalg', 'Hvilken organisasjon ble opprettet i 1945 for å sikre fred?', array['FN', 'Folkeforbundet', 'EU', 'LO']::text[], 0, 'FN erstattet Folkeforbundet, som ikke hadde klart å hindre krigen.', true, false, 9),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'm01', 'sant-usant', 'Vidkun Quisling ledet Nasjonal Samling under okkupasjonen.', array['Sant', 'Usant']::text[], 0, 'Etter krigen ble han dømt til døden for landssvik.', false, true, 10),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'm02', 'sant-usant', 'Flere soldater enn sivile døde i andre verdenskrig.', array['Sant', 'Usant']::text[], 1, 'Flere sivile enn soldater døde, blant annet i Holocaust og bombingen av byer.', false, true, 11),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'm03', 'sant-usant', 'USA gikk inn i krigen etter Japans angrep på Pearl Harbor.', array['Sant', 'Usant']::text[], 0, 'Angrepet skjedde i desember 1941.', false, true, 12),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'm04', 'sant-usant', 'Norge ble frigjort allerede i 1942.', array['Sant', 'Usant']::text[], 1, 'Norge var okkupert i fem år, fram til 8. mai 1945.', false, true, 13),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'm05', 'flervalg', 'Hva er antisemittisme?', array['Hat og fordommer mot jøder', 'Motstand mot krig', 'Støtte til demokrati', 'En type økonomi']::text[], 0, 'Antisemittisme var en kjerne i nazismen.', false, true, 14),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'm06', 'flervalg', 'Hvem styrte Sovjetunionen under andre verdenskrig?', array['Lenin', 'Mussolini', 'Stalin', 'Churchill']::text[], 2, 'Stalin styrte Sovjetunionen fra slutten av 1920-tallet til han døde i 1953.', false, true, 15),
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 'm07', 'flervalg', 'Hva skjedde på D-dagen?', array['Tyskland angrep Norge', 'De allierte gikk i land i Normandie', 'Krigen sluttet', 'Den første atombomben ble sluppet']::text[], 1, 'Landgangen 6. juni 1944 åpnet en ny front i vest.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-9:mellomkrigstid-og-andre-verdenskrig', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-9:holocaust-og-folkemord', 'samfunnsfag-9', 'holocaust-og-folkemord', 'Holocaust og andre folkemord', 'Hva folkemord er, hvordan Holocaust skjedde steg for steg, også i Norge, andre folkemord i nyere tid, og hvordan ekstreme holdninger og handlinger kan forebygges.', array[8]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-9:holocaust-og-folkemord', '## Hva er folkemord?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-9:holocaust-og-folkemord', 'Folkemord', 'Handlinger med hensikt å ødelegge en nasjonal, etnisk, religiøs eller «rasemessig» gruppe.', 0),
  ('samfunnsfag-9:holocaust-og-folkemord', 'Folkemordkonvensjonen', 'FN-avtale fra 1948 som gjør folkemord til en internasjonal forbrytelse.', 1),
  ('samfunnsfag-9:holocaust-og-folkemord', 'Holocaust', 'Nazistenes systematiske drap på rundt seks millioner jøder.', 2),
  ('samfunnsfag-9:holocaust-og-folkemord', 'Antisemittisme', 'Hat og fordommer mot jøder.', 3),
  ('samfunnsfag-9:holocaust-og-folkemord', 'Nürnberglovene', 'Nazistiske lover fra 1935 som fratok jøder rettigheter.', 4),
  ('samfunnsfag-9:holocaust-og-folkemord', 'Krystallnatten', 'Angrep på synagoger og jødiske butikker i Tyskland i november 1938.', 5),
  ('samfunnsfag-9:holocaust-og-folkemord', 'Ghetto', 'Avstengt bydel der jøder ble tvunget til å bo under svært dårlige forhold.', 6),
  ('samfunnsfag-9:holocaust-og-folkemord', 'Utryddelsesleir', 'Leir bygd for å drepe mennesker, som Auschwitz-Birkenau og Treblinka.', 7),
  ('samfunnsfag-9:holocaust-og-folkemord', 'Donau', 'Skipet som 26. november 1942 fraktet over 500 jøder fra Oslo.', 8),
  ('samfunnsfag-9:holocaust-og-folkemord', 'Avhumanisering', 'Å fremstille en gruppe som mindre menneskelig, ofte i propaganda.', 9),
  ('samfunnsfag-9:holocaust-og-folkemord', 'Tilskuer', 'En som ser hva som skjer, men ikke griper inn.', 10),
  ('samfunnsfag-9:holocaust-og-folkemord', 'Rwanda 1994', 'Folkemord der rundt 800 000 tutsier og moderate hutuer ble drept på omtrent 100 dager.', 11),
  ('samfunnsfag-9:holocaust-og-folkemord', 'Srebrenica 1995', 'Folkemord i Bosnia der om lag 8000 bosniakiske menn og gutter ble drept.', 12),
  ('samfunnsfag-9:holocaust-og-folkemord', 'Nürnbergprosessen', 'Rettssakene mot nazistiske ledere etter andre verdenskrig.', 13),
  ('samfunnsfag-9:holocaust-og-folkemord', 'ICC', 'Den internasjonale straffedomstolen, opprettet i 2002.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-9:holocaust-og-folkemord', 'q01', 'flervalg', 'Hva er folkemord?', array['Handlinger med hensikt å ødelegge en nasjonal, etnisk, religiøs eller «rasemessig» gruppe', 'Alle drap i krig', 'En borgerkrig', 'Et terrorangrep']::text[], 0, 'Det avgjørende er hensikten om å ødelegge gruppen.', true, true, 0),
  ('samfunnsfag-9:holocaust-og-folkemord', 'q02', 'flervalg', 'Omtrent hvor mange jøder ble drept i Holocaust?', array['Rundt 600 000', 'Rundt 1 million', 'Rundt 6 millioner', 'Rundt 60 millioner']::text[], 2, 'Omtrent to av tre jøder i Europa ble drept.', true, true, 1),
  ('samfunnsfag-9:holocaust-og-folkemord', 'q03', 'flervalg', 'Hva var Nürnberglovene fra 1935?', array['Fredsavtaler etter krigen', 'Lover som fratok jøder rettigheter', 'Lover om arbeidstid', 'Regler for de olympiske lekene']::text[], 1, 'Lovene gjorde jøder til annenrangs borgere og forbød blant annet ekteskap med ikke-jøder.', true, true, 2),
  ('samfunnsfag-9:holocaust-og-folkemord', 'q04', 'flervalg', 'Hva skjedde 26. november 1942?', array['Tyskland kapitulerte', 'Krystallnatten', 'Nürnbergprosessen startet', 'Over 500 jøder ble sendt fra Oslo med skipet Donau']::text[], 3, 'De fleste av dem ble drept i Auschwitz.', true, true, 3),
  ('samfunnsfag-9:holocaust-og-folkemord', 'q05', 'flervalg', 'Hva betyr avhumanisering?', array['Å fremstille en gruppe som mindre menneskelig', 'Å hjelpe flyktninger', 'Å lære om historie', 'Å dele ut mat']::text[], 0, 'Avhumanisering gjør det lettere å rettferdiggjøre vold mot en gruppe.', true, true, 4),
  ('samfunnsfag-9:holocaust-og-folkemord', 'q06', 'flervalg', 'Hvor skjedde folkemordet i 1994, der rundt 800 000 ble drept på omtrent 100 dager?', array['Kambodsja', 'Bosnia', 'Armenia', 'Rwanda']::text[], 3, 'Ofrene var tutsier og moderate hutuer.', true, true, 5),
  ('samfunnsfag-9:holocaust-og-folkemord', 'q07', 'flervalg', 'Hvorfor er tilskuere viktige når vi snakker om folkemord?', array['Fordi de alltid stopper drapene', 'Fordi folkemord blir lettere å gjennomføre når mange ser bort', 'Fordi de er gjerningspersoner', 'De er ikke viktige']::text[], 1, 'Når få sier ifra, møter gjerningspersonene lite motstand.', true, true, 6),
  ('samfunnsfag-9:holocaust-og-folkemord', 'q08', 'flervalg', 'Hva var Nürnbergprosessen?', array['Et opprør i en ghetto', 'Et folkemord i Tyskland', 'Rettssaker mot nazistiske ledere etter krigen', 'En tysk propagandakampanje']::text[], 2, 'Rettssakene slo fast at ledere kan straffes for forbrytelser mot menneskeheten.', true, true, 7),
  ('samfunnsfag-9:holocaust-og-folkemord', 'q09', 'flervalg', 'Hvilket tiltak kan bidra til å forebygge ekstreme holdninger?', array['Å spre konspirasjonsteorier', 'Å overse hatprat', 'Å svekke rettsstaten', 'Kunnskap og kildekritikk']::text[], 3, 'Kunnskap gjør det lettere å gjenkjenne propaganda og fordommer.', true, false, 8),
  ('samfunnsfag-9:holocaust-og-folkemord', 'q10', 'flervalg', 'Hvilke andre grupper enn jøder forfulgte og drepte nazistene?', array['Rom, mennesker med funksjonsnedsettelser og politiske motstandere', 'Bare soldater', 'Ingen andre', 'Bare britiske fanger']::text[], 0, 'Nazistene forfulgte alle de mente ikke passet inn i «folkefellesskapet».', true, false, 9),
  ('samfunnsfag-9:holocaust-og-folkemord', 'm01', 'sant-usant', 'Folkemord starter ofte med fordommer, propaganda og diskriminerende lover.', array['Sant', 'Usant']::text[], 0, 'Holocaust skjedde steg for steg over flere år.', false, true, 10),
  ('samfunnsfag-9:holocaust-og-folkemord', 'm02', 'sant-usant', 'Norsk politi deltok i arrestasjonen av jøder i Norge.', array['Sant', 'Usant']::text[], 0, 'Norske politifolk arresterte jøder og fraktet dem til skipet Donau.', false, true, 11),
  ('samfunnsfag-9:holocaust-og-folkemord', 'm03', 'sant-usant', 'Det har ikke skjedd folkemord etter andre verdenskrig.', array['Sant', 'Usant']::text[], 1, 'Blant annet Kambodsja, Rwanda og Srebrenica er eksempler fra senere tid.', false, true, 12),
  ('samfunnsfag-9:holocaust-og-folkemord', 'm04', 'sant-usant', 'Folkemordkonvensjonen ble vedtatt av FN i 1998.', array['Sant', 'Usant']::text[], 1, 'Konvensjonen ble vedtatt i 1948.', false, true, 13),
  ('samfunnsfag-9:holocaust-og-folkemord', 'm05', 'flervalg', 'Hva var Auschwitz-Birkenau?', array['En ghetto i Warszawa', 'Nazistenes største utryddelsesleir', 'En fredsavtale', 'Et norsk fengsel']::text[], 1, 'Over én million mennesker ble drept der, de fleste jøder.', false, true, 14),
  ('samfunnsfag-9:holocaust-og-folkemord', 'm06', 'flervalg', 'Hva skjedde under Krystallnatten i 1938?', array['Synagoger og jødiske butikker ble angrepet', 'Tyskland angrep Polen', 'Hitler ble rikskansler', 'Norge ble okkupert']::text[], 0, 'Navnet kommer av alle knuste vinduer.', false, true, 15),
  ('samfunnsfag-9:holocaust-og-folkemord', 'm07', 'flervalg', 'Hvilken domstol ble opprettet i 2002 for å straffe folkemord og andre alvorlige forbrytelser?', array['Høyesterett', 'EU-domstolen', 'Den internasjonale straffedomstolen (ICC)', 'Den europeiske menneskerettsdomstolen']::text[], 2, 'ICC ligger i Haag i Nederland.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-9:holocaust-og-folkemord', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'samfunnsfag-9', 'fornorsking-og-minoriteter', 'Fornorsking, samer og nasjonale minoriteter', 'Hvordan samer og de nasjonale minoritetene ble utsatt for fornorsking og urett, hvilke konsekvenser det har hatt for enkeltmennesker og samfunnet, og hvordan arbeidet med oppreisning har foregått.', array[10]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-9:fornorsking-og-minoriteter', '## Samer og nasjonale minoriteter
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'Urfolk', 'Folk som har bodd i et område før dagens statsgrenser ble trukket, og som har egen kultur og egne samfunnsinstitusjoner.', 0),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'Sápmi', 'Samenes område i Norge, Sverige, Finland og Russland.', 1),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'Nasjonale minoriteter', 'Jøder, kvener/norskfinner, skogfinner, rom og romanifolk/tatere.', 2),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'Fornorsking', 'Statens politikk for at minoriteter skulle bli norske i språk og kultur.', 3),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'Internatskole', 'Skole der elevene bodde borte fra familien. Brukt i fornorskingen.', 4),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'Jordsalgsloven', 'Lov fra 1902 om at bare de som kunne norsk, fikk kjøpe jord i Finnmark.', 5),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'Rasetenkning', 'Ideen om at noen folkegrupper er mer verdt enn andre.', 6),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'Romanifolket/taterne', 'Nasjonal minoritet som ble utsatt for tvangssterilisering og omsorgsovertakelser.', 7),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'Svanviken arbeidskoloni', 'Sted der romanifamilier ble sendt for å bli «bofaste» og tilpasset.', 8),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'Kvener', 'Nasjonal minoritet med finsk bakgrunn i Nord-Norge.', 9),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'Sametinget', 'Samenes folkevalgte organ, opprettet i 1989.', 10),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'ILO-konvensjon 169', 'Avtale om urfolks rettigheter. Norge ratifiserte den som første land i 1990.', 11),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'Sannhets- og forsoningskommisjonen', 'Kommisjon som i 2023 la fram en rapport om fornorskingen og uretten.', 12),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'Revitalisering', 'At et språk eller en kultur tas i bruk og styrkes igjen.', 13),
  ('samfunnsfag-9:fornorsking-og-minoriteter', '6. februar', 'Samenes nasjonaldag.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'q01', 'flervalg', 'Hva er fornorsking?', array['Politikk for at minoriteter skulle bli norske i språk og kultur', 'At nordmenn lærte samisk', 'At Norge ble selvstendig', 'En type skoleeksamen']::text[], 0, 'Fornorskingspolitikken varte i over hundre år.', true, true, 0),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'q02', 'flervalg', 'Hvor mange nasjonale minoriteter har Norge?', array['To', 'Tre', 'Fem', 'Åtte']::text[], 2, 'Jøder, kvener/norskfinner, skogfinner, rom og romanifolk/tatere.', true, true, 1),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'q03', 'flervalg', 'Hva bestemte jordsalgsloven av 1902?', array['At alle fikk gratis jord', 'At bare de som kunne norsk, fikk kjøpe jord i Finnmark', 'At samer eide all jord', 'At jord ikke kunne selges']::text[], 1, 'Loven presset samer og kvener til å bli norske.', true, true, 2),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'q04', 'flervalg', 'Hvordan ble mange samiske barn rammet av internatskolene?', array['De lærte flere språk', 'De fikk bo hjemme', 'De fikk undervisning på samisk', 'De ble sendt langt hjemmefra og kunne bli straffet for å snakke morsmålet']::text[], 3, 'Mange mistet språket og kontakten med sin egen kultur.', true, true, 3),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'q05', 'flervalg', 'Hva er en konsekvens av fornorskingen for den enkelte?', array['Skam over egen bakgrunn og tap av språk', 'At alle ble tospråklige', 'Høyere lønn', 'Flere samiske aviser']::text[], 0, 'Mange foreldre sluttet å snakke morsmålet med barna sine.', true, true, 4),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'q06', 'flervalg', 'Hvilken gruppe ble utsatt for tvangssterilisering og fikk barn tatt fra seg?', array['Skogfinnene', 'Romanifolket/taterne', 'Kvenene', 'Jødene']::text[], 1, 'Staten og Norsk misjon blant hjemløse sto bak store overgrep.', true, true, 5),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'q07', 'flervalg', 'Hvilken institusjon ble opprettet i 1989?', array['Stortinget', 'Høyesterett', 'Sametinget', 'Datatilsynet']::text[], 2, 'Sametinget ligger i Karasjok.', true, true, 6),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'q08', 'flervalg', 'Hva var en av begrunnelsene for fornorskingspolitikken?', array['Ønsket om mer mangfold', 'Ønsket om flere språk i skolen', 'Krav fra FN', 'Frykt for at minoritetene var lojale mot Finland eller Russland']::text[], 3, 'Myndighetene så på minoritetene i nord som en sikkerhetsrisiko.', true, true, 7),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'q09', 'flervalg', 'Hva er ILO-konvensjon 169?', array['En avtale om arbeidstid', 'En avtale om urfolks rettigheter', 'En fredsavtale', 'En handelsavtale']::text[], 1, 'Norge var det første landet som ratifiserte den.', true, false, 8),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'q10', 'flervalg', 'Hva la Sannhets- og forsoningskommisjonen fram i 2023?', array['En rapport om fornorskingen og uretten mot samer, kvener og skogfinner', 'Et forslag til nytt flagg', 'En ny skolereform', 'Et nytt statsbudsjett']::text[], 0, 'Rapporten beskriver uretten og foreslår tiltak for forsoning.', true, false, 9),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'm01', 'sant-usant', 'Samene bodde i Sápmi lenge før dagens landegrenser ble trukket.', array['Sant', 'Usant']::text[], 0, 'Derfor regnes samene som et urfolk.', false, true, 10),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'm02', 'sant-usant', 'Rom ble nektet innreise til Norge fra 1927.', array['Sant', 'Usant']::text[], 0, 'Forbudet gjorde at mange rom ikke fikk komme til Norge og ble drept under Holocaust.', false, true, 11),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'm03', 'sant-usant', 'Fornorskingspolitikken ble avsluttet allerede rundt 1880.', array['Sant', 'Usant']::text[], 1, 'Politikken varte til godt etter andre verdenskrig.', false, true, 12),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'm04', 'sant-usant', 'Konsekvensene av fornorskingen merkes ikke lenger i dag.', array['Sant', 'Usant']::text[], 1, 'Språktap, traumer og mistillit preger fortsatt mange familier og lokalsamfunn.', false, true, 13),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'm05', 'flervalg', 'Hvilken gruppe er ikke en nasjonal minoritet i Norge?', array['Kvener/norskfinner', 'Skogfinner', 'Samer', 'Rom']::text[], 2, 'Samene har status som urfolk, ikke som nasjonal minoritet.', false, true, 14),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'm06', 'flervalg', 'Når feirer samene nasjonaldagen sin?', array['6. februar', '17. mai', '9. april', '24. juni']::text[], 0, 'Datoen minner om det første samiske landsmøtet i Trondheim i 1917.', false, true, 15),
  ('samfunnsfag-9:fornorsking-og-minoriteter', 'm07', 'flervalg', 'Hvem ba samene om unnskyldning i 1997?', array['Statsministeren', 'Kong Harald', 'Sametingspresidenten', 'FNs generalsekretær']::text[], 1, 'Kongen ba om unnskyldning i talen ved åpningen av Sametinget.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-9:fornorsking-og-minoriteter', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-9:menneskerettigheter', 'samfunnsfag-9', 'menneskerettigheter', 'Menneskerettigheter og internasjonalt samarbeid', 'Hva menneskerettigheter og urfolksrettigheter er, hvilke internasjonale avtaler som sikrer dem, og hvilken betydning de har for norsk politikk, likestilling og likeverd.', array[9]::int[], 6, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-9:menneskerettigheter', '## Hva er menneskerettigheter?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-9:menneskerettigheter', 'Menneskerettigheter', 'Grunnleggende rettigheter alle har fordi de er mennesker.', 0),
  ('samfunnsfag-9:menneskerettigheter', 'Universelle', 'Menneskerettighetene gjelder alle mennesker, overalt.', 1),
  ('samfunnsfag-9:menneskerettigheter', 'Verdenserklæringen', 'FNs erklæring om menneskerettighetene fra 10. desember 1948, med 30 artikler.', 2),
  ('samfunnsfag-9:menneskerettigheter', 'Konvensjon', 'Avtale som er juridisk bindende for statene som slutter seg til den.', 3),
  ('samfunnsfag-9:menneskerettigheter', 'Barnekonvensjonen', 'FN-avtale fra 1989 om rettighetene til barn under 18 år.', 4),
  ('samfunnsfag-9:menneskerettigheter', 'Kvinnediskrimineringskonvensjonen', 'FN-avtale fra 1979 mot diskriminering av kvinner.', 5),
  ('samfunnsfag-9:menneskerettigheter', 'EMK', 'Den europeiske menneskerettskonvensjonen fra 1950.', 6),
  ('samfunnsfag-9:menneskerettigheter', 'Menneskerettsdomstolen', 'Den europeiske domstolen i Strasbourg som dømmer i saker etter EMK.', 7),
  ('samfunnsfag-9:menneskerettigheter', 'Menneskerettsloven', 'Norsk lov fra 1999 som gjør viktige konvensjoner til norsk lov.', 8),
  ('samfunnsfag-9:menneskerettigheter', 'ILO-konvensjon 169', 'Avtale fra 1989 om urfolks rettigheter, blant annet til å bli konsultert.', 9),
  ('samfunnsfag-9:menneskerettigheter', 'Fosen-saken', 'Høyesterett slo i 2021 fast at vindkraftverk krenket samiske reindriftsutøveres rettigheter.', 10),
  ('samfunnsfag-9:menneskerettigheter', 'Likeverd', 'At alle mennesker har samme verdi.', 11),
  ('samfunnsfag-9:menneskerettigheter', 'Likestilling', 'At alle har like muligheter og rettigheter, uansett for eksempel kjønn eller etnisitet.', 12),
  ('samfunnsfag-9:menneskerettigheter', 'Diskriminering', 'Usaklig forskjellsbehandling av mennesker.', 13),
  ('samfunnsfag-9:menneskerettigheter', 'Amnesty International', 'Organisasjon som avdekker og protesterer mot brudd på menneskerettighetene.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-9:menneskerettigheter', 'q01', 'flervalg', 'Når vedtok FN verdenserklæringen om menneskerettighetene?', array['1945', '1948', '1989', '2007']::text[], 1, '10. desember markeres som menneskerettighetsdagen.', true, true, 0),
  ('samfunnsfag-9:menneskerettigheter', 'q02', 'flervalg', 'Hva betyr det at menneskerettighetene er universelle?', array['At de gjelder alle mennesker', 'At de bare gjelder i Europa', 'At de kan kjøpes', 'At de bare gjelder voksne']::text[], 0, 'Rettighetene gjelder uansett hvor du bor, og hvem du er.', true, true, 1),
  ('samfunnsfag-9:menneskerettigheter', 'q03', 'flervalg', 'Hva er forskjellen på en erklæring og en konvensjon?', array['Det er ingen forskjell', 'En erklæring er strengere', 'En konvensjon er bindende for statene som slutter seg til den', 'En konvensjon gjelder bare barn']::text[], 2, 'Erklæringer er viktige politiske signaler, men konvensjoner er juridisk bindende.', true, true, 2),
  ('samfunnsfag-9:menneskerettigheter', 'q04', 'flervalg', 'Hvem har hovedansvaret for å sikre menneskerettighetene?', array['Den enkelte', 'Bedrifter', 'Amnesty International', 'Staten']::text[], 3, 'Staten skal respektere, beskytte og oppfylle rettighetene.', true, true, 3),
  ('samfunnsfag-9:menneskerettigheter', 'q05', 'flervalg', 'Hva slo Høyesterett fast i Fosen-saken i 2021?', array['At vindkraftverk krenket rettighetene til samiske reindriftsutøvere', 'At vindkraft er ulovlig i Norge', 'At reindrift skal avvikles', 'At samene ikke er urfolk']::text[], 0, 'Dommen viser hvordan urfolksrettigheter påvirker norsk politikk.', true, true, 4),
  ('samfunnsfag-9:menneskerettigheter', 'q06', 'flervalg', 'Hvilken konvensjon gir barn rett til å bli hørt?', array['ILO-konvensjon 169', 'Barnekonvensjonen', 'EMK', 'Kvinnediskrimineringskonvensjonen']::text[], 1, 'Barn har rett til å si sin mening i saker som angår dem.', true, true, 5),
  ('samfunnsfag-9:menneskerettigheter', 'q07', 'flervalg', 'Hvor ligger Den europeiske menneskerettsdomstolen?', array['Oslo', 'New York', 'Genève', 'Strasbourg']::text[], 3, 'Domstolen hører til Europarådet, ikke EU.', true, true, 6),
  ('samfunnsfag-9:menneskerettigheter', 'q08', 'flervalg', 'Hvordan påvirker menneskerettskonvensjonene norsk politikk?', array['De har ingen betydning', 'Norske lover må være i tråd med dem', 'De gjelder bare utenfor Norge', 'De bestemmer hvem som blir statsminister']::text[], 1, 'Menneskerettsloven gir konvensjonene forrang foran vanlig norsk lov ved motstrid.', true, true, 7),
  ('samfunnsfag-9:menneskerettigheter', 'q09', 'flervalg', 'Hva betyr likestilling?', array['At alle skal ha like muligheter og rettigheter', 'At alle skal være like', 'At alle skal tjene det samme', 'At kvinner og menn skal ha samme yrke']::text[], 0, 'Likestilling handler om muligheter og rettigheter, ikke om at alle skal velge det samme.', true, false, 8),
  ('samfunnsfag-9:menneskerettigheter', 'q10', 'flervalg', 'Hvilken rettighet gir ILO-konvensjon 169 urfolk?', array['Rett til gratis strøm', 'Rett til å slippe skatt', 'Rett til å bli konsultert i saker som angår dem', 'Rett til egen hær']::text[], 2, 'Staten må for eksempel konsultere Sametinget før vedtak som berører samene.', true, false, 9),
  ('samfunnsfag-9:menneskerettigheter', 'm01', 'sant-usant', 'Verdenserklæringen om menneskerettighetene er juridisk bindende.', array['Sant', 'Usant']::text[], 1, 'Erklæringen er ikke bindende, men konvensjonene som bygger på den, er det.', false, true, 10),
  ('samfunnsfag-9:menneskerettigheter', 'm02', 'sant-usant', 'Norge kan bli dømt i Den europeiske menneskerettsdomstolen.', array['Sant', 'Usant']::text[], 0, 'Norge er blant annet dømt i flere barnevernssaker.', false, true, 11),
  ('samfunnsfag-9:menneskerettigheter', 'm03', 'sant-usant', 'Grunnloven har et eget kapittel om menneskerettigheter.', array['Sant', 'Usant']::text[], 0, 'Kapittelet kom inn i Grunnloven i 2014.', false, true, 12),
  ('samfunnsfag-9:menneskerettigheter', 'm04', 'sant-usant', 'Menneskerettighetene gjelder bare for statsborgere.', array['Sant', 'Usant']::text[], 1, 'Menneskerettighetene gjelder alle mennesker.', false, true, 13),
  ('samfunnsfag-9:menneskerettigheter', 'm05', 'flervalg', 'Hvor mange artikler har verdenserklæringen?', array['10', '30', '50', '100']::text[], 1, 'De 30 artiklene dekker både sivile, politiske, økonomiske og sosiale rettigheter.', false, true, 14),
  ('samfunnsfag-9:menneskerettigheter', 'm06', 'flervalg', 'Hvem kan hjelpe deg hvis du opplever diskriminering?', array['Likestillings- og diskrimineringsombudet', 'Datatilsynet', 'Forbrukerrådet', 'Skatteetaten']::text[], 0, 'Ombudet gir gratis veiledning om diskriminering.', false, true, 15),
  ('samfunnsfag-9:menneskerettigheter', 'm07', 'flervalg', 'Hva gjør Amnesty International?', array['Vedtar lover', 'Dømmer i straffesaker', 'Avdekker og protesterer mot brudd på menneskerettighetene', 'Leder FN']::text[], 2, 'Amnesty er en frivillig organisasjon med medlemmer over hele verden.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-9:menneskerettigheter', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-9:hinduismen', 'krle-9', 'hinduismen', 'Hinduismen', 'Hellige skrifter, sentrale begreper som karma, samsara og moksha, guder og gudinner, veiene til frigjøring, praksis og høytider, og kastesystemet i hinduismen.', array[1, 6]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-9:hinduismen', '## En eldgammel religion
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-9:hinduismen', 'Hinduisme', 'Verdens tredje største religion, uten grunnlegger, med røtter over 3000 år tilbake.', 0),
  ('krle-9:hinduismen', 'Vedaene', 'Hinduismens eldste hellige skrifter, med hymner og ritualer.', 1),
  ('krle-9:hinduismen', 'Bhagavadgita', 'Del av eposet Mahabharata og en av de mest leste hinduistiske tekstene.', 2),
  ('krle-9:hinduismen', 'Brahman', 'Den guddommelige kraften som er i alt og bak alt.', 3),
  ('krle-9:hinduismen', 'Atman', 'Menneskets sjel eller innerste selv.', 4),
  ('krle-9:hinduismen', 'Samsara', 'Kretsløpet av fødsel, død og gjenfødelse.', 5),
  ('krle-9:hinduismen', 'Karma', 'Loven om at alle handlinger får følger, i dette eller et senere liv.', 6),
  ('krle-9:hinduismen', 'Dharma', 'Plikten og den rette måten å leve på.', 7),
  ('krle-9:hinduismen', 'Moksha', 'Frigjøring fra samsara, det endelige målet.', 8),
  ('krle-9:hinduismen', 'Brahma, Vishnu og Shiva', 'Skaperen, opprettholderen og den som ødelegger og fornyer.', 9),
  ('krle-9:hinduismen', 'Avatar', 'En skikkelse en gud tar når den kommer til jorda, som Rama og Krishna.', 10),
  ('krle-9:hinduismen', 'Bhakti', 'Hengivelsens vei: kjærlighet til og tilbedelse av en gud.', 11),
  ('krle-9:hinduismen', 'Puja', 'Tilbedelse der man ofrer blomster, mat, lys og røkelse til gudebilder.', 12),
  ('krle-9:hinduismen', 'Divali', 'Lysfesten, en av hinduismens største høytider.', 13),
  ('krle-9:hinduismen', 'Dalitter', 'Grupper utenfor kastesystemet som har vært utsatt for grov diskriminering.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-9:hinduismen', 'q01', 'flervalg', 'Hvor bor de fleste hinduer?', array['Kina', 'Indonesia', 'Sri Lanka', 'India og Nepal']::text[], 3, 'Omtrent åtte av ti indere er hinduer.', true, true, 0),
  ('krle-9:hinduismen', 'q02', 'flervalg', 'Hva er samsara?', array['Frigjøring fra gjenfødelse', 'Kretsløpet av fødsel, død og gjenfødelse', 'En hellig elv', 'En type tempel']::text[], 1, 'Målet er å bli fri fra samsara.', true, true, 1),
  ('krle-9:hinduismen', 'q03', 'flervalg', 'Hva betyr karma?', array['At alle handlinger får følger', 'Den guddommelige kraften i alt', 'Plikten til å be', 'En høytid']::text[], 0, 'Gode og dårlige handlinger påvirker hvordan man blir født på nytt.', true, true, 2),
  ('krle-9:hinduismen', 'q04', 'flervalg', 'Hva er moksha?', array['Et tempel', 'En gudinne', 'Frigjøring fra samsara', 'En type yoga']::text[], 2, 'Moksha er det endelige målet i hinduismen.', true, true, 3),
  ('krle-9:hinduismen', 'q05', 'flervalg', 'Hvilken gud kalles opprettholderen og kommer til jorda som avatarer?', array['Shiva', 'Vishnu', 'Brahma', 'Ganesha']::text[], 1, 'Rama og Krishna regnes som avatarer av Vishnu.', true, true, 4),
  ('krle-9:hinduismen', 'q06', 'flervalg', 'Hva er puja?', array['En hellig bok', 'En kaste', 'En pilegrimsby', 'Tilbedelse med offergaver til gudebilder']::text[], 3, 'Puja kan gjøres ved et alter hjemme eller i tempelet.', true, true, 5),
  ('krle-9:hinduismen', 'q07', 'flervalg', 'Hva er Bhagavadgita?', array['En del av eposet Mahabharata', 'Den eldste vedaen', 'En lysfest', 'Et tempel i Varanasi']::text[], 0, 'Teksten er en samtale mellom guden Krishna og krigeren Arjuna.', true, true, 6),
  ('krle-9:hinduismen', 'q08', 'flervalg', 'Hva er divali?', array['Fargefesten om våren', 'En faste', 'Lysfesten', 'En pilegrimsreise']::text[], 2, 'Under divali tennes lys og lamper som symbol på at det gode seirer.', true, true, 7),
  ('krle-9:hinduismen', 'q09', 'flervalg', 'Hva sier Indias grunnlov om kastediskriminering?', array['At den er påbudt', 'At den bare gjelder i byene', 'At den er en del av religionen', 'At den er forbudt']::text[], 3, 'Grunnloven fra 1950 forbyr diskriminering på grunn av kaste.', true, false, 8),
  ('krle-9:hinduismen', 'q10', 'flervalg', 'Hva er atman?', array['Menneskets sjel eller innerste selv', 'En gud med elefanthode', 'En hellig ku', 'Et epos']::text[], 0, 'Mange hinduer mener at atman i bunn og grunn er ett med Brahman.', true, false, 9),
  ('krle-9:hinduismen', 'm01', 'sant-usant', 'Hinduismen har én grunnlegger, slik kristendommen har Jesus.', array['Sant', 'Usant']::text[], 1, 'Hinduismen har vokst fram gradvis og har ingen grunnlegger.', false, true, 10),
  ('krle-9:hinduismen', 'm02', 'sant-usant', 'Mange hinduer ser de ulike gudene som sider av det samme guddommelige.', array['Sant', 'Usant']::text[], 0, 'Gudene kan forstås som uttrykk for Brahman.', false, true, 11),
  ('krle-9:hinduismen', 'm03', 'sant-usant', 'Yoga har røtter i hinduismen.', array['Sant', 'Usant']::text[], 0, 'Yoga var opprinnelig en vei til åndelig innsikt.', false, true, 12),
  ('krle-9:hinduismen', 'm04', 'sant-usant', 'Alle hinduer følger nøyaktig den samme læren.', array['Sant', 'Usant']::text[], 1, 'Hinduismen rommer svært mange ulike tradisjoner.', false, true, 13),
  ('krle-9:hinduismen', 'm05', 'flervalg', 'Hva kalles hengivelsens vei?', array['Karma', 'Bhakti', 'Dharma', 'Puja']::text[], 1, 'Bhakti er den mest utbredte veien blant hinduer i dag.', false, true, 14),
  ('krle-9:hinduismen', 'm06', 'flervalg', 'Hvilken by ved Ganges er et viktig pilegrimsmål?', array['Delhi', 'Mumbai', 'Varanasi', 'Kolkata']::text[], 2, 'Mange ønsker å bli kremert i Varanasi og få asken strødd i Ganges.', false, true, 15),
  ('krle-9:hinduismen', 'm07', 'flervalg', 'Hva er dharma?', array['Plikten og den rette måten å leve på', 'En hellig elv', 'En type meditasjon', 'En gudinne']::text[], 0, 'Dharma kan være ulik for ulike mennesker og livsfaser.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-9:hinduismen', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-9:buddhismen', 'krle-9', 'buddhismen', 'Buddhismen', 'Buddhas liv, de fire edle sannheter og den åttedelte vei, de tre juvelene, de viktigste retningene i buddhismen og buddhistisk praksis i dag.', array[1, 6]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-9:buddhismen', '## Buddhismen i verden
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-9:buddhismen', 'Buddhisme', 'Religion som oppsto i India for rundt 2500 år siden, med rundt en halv milliard tilhengere.', 0),
  ('krle-9:buddhismen', 'Siddhartha Gautama', 'Prinsen som ble Buddha. Født i Lumbini i dagens Nepal.', 1),
  ('krle-9:buddhismen', 'Buddha', '«Den oppvåknede».', 2),
  ('krle-9:buddhismen', 'De fire møtene', 'En gammel mann, en syk mann, et lik og en asket, som fikk Siddhartha til å forlate palasset.', 3),
  ('krle-9:buddhismen', 'Middelveien', 'Å unngå både luksus og streng askese.', 4),
  ('krle-9:buddhismen', 'De fire edle sannheter', 'Lidelse, årsaken til lidelse, at lidelsen kan opphøre, og veien dit.', 5),
  ('krle-9:buddhismen', 'Dukkha', 'Lidelse og utilfredshet, som ifølge buddhismen preger livet.', 6),
  ('krle-9:buddhismen', 'Den åttedelte vei', 'Veien ut av lidelsen, delt i visdom, moral og meditasjon.', 7),
  ('krle-9:buddhismen', 'Nirvana', 'Tilstanden der lidelsen og gjenfødelsen opphører.', 8),
  ('krle-9:buddhismen', 'De tre juvelene', 'Buddha, dharma (læren) og sangha (fellesskapet).', 9),
  ('krle-9:buddhismen', 'Sangha', 'Fellesskapet av munker, nonner og troende.', 10),
  ('krle-9:buddhismen', 'Theravada', 'Buddhistisk retning i Sri Lanka, Thailand og Myanmar, med vekt på klosterliv.', 11),
  ('krle-9:buddhismen', 'Mahayana', 'Buddhistisk retning i Kina, Japan, Korea og Vietnam, med vekt på bodhisattvaer.', 12),
  ('krle-9:buddhismen', 'Dalai Lama', 'Leder i tibetansk buddhisme.', 13),
  ('krle-9:buddhismen', 'Vesak', 'Høytid til minne om Buddhas fødsel, oppvåkning og død.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-9:buddhismen', 'q01', 'flervalg', 'Hva betyr Buddha?', array['Den oppvåknede', 'Den hellige', 'Kongen', 'Læreren fra India']::text[], 0, 'Siddhartha ble kalt Buddha etter oppvåkningen under treet i Bodh Gaya.', true, true, 0),
  ('krle-9:buddhismen', 'q02', 'flervalg', 'Hva fikk Siddhartha til å forlate palasset?', array['Møter med kongen og dronningen', 'Møter med fire munker i et tempel', 'Møter med en gammel mann, en syk mann, et lik og en asket', 'Møter med fire guder']::text[], 2, 'Møtene viste ham at alle mennesker rammes av lidelse.', true, true, 1),
  ('krle-9:buddhismen', 'q03', 'flervalg', 'Hva sier den første edle sannheten?', array['At alle skal bli munker', 'At lidelsen kan opphøre', 'At veien er den åttedelte vei', 'At livet er preget av lidelse']::text[], 3, 'Buddhismen starter med å erkjenne at livet inneholder lidelse og utilfredshet.', true, true, 2),
  ('krle-9:buddhismen', 'q04', 'flervalg', 'Hva skyldes lidelsen ifølge buddhismen?', array['Gudene', 'Begjær og tørst etter ting', 'Dårlig vær', 'Fattigdom']::text[], 1, 'Vi lider fordi vi holder fast på ting som forandrer seg.', true, true, 3),
  ('krle-9:buddhismen', 'q05', 'flervalg', 'Hva er nirvana?', array['Tilstanden der lidelsen og gjenfødelsen opphører', 'En hellig by', 'Et kloster', 'En gud']::text[], 0, 'Nirvana er målet for buddhister.', true, true, 4),
  ('krle-9:buddhismen', 'q06', 'flervalg', 'Hva er middelveien?', array['En vei gjennom India', 'Å leve som prins', 'Å unngå både luksus og streng askese', 'En type meditasjon']::text[], 2, 'Buddha hadde prøvd både overflod og selvpining.', true, true, 5),
  ('krle-9:buddhismen', 'q07', 'flervalg', 'Hva er de tre juvelene?', array['Tre hellige steiner', 'Buddha, læren (dharma) og fellesskapet (sangha)', 'Tre store templer', 'Tre høytider']::text[], 1, 'Å søke tilflukt i de tre juvelene er å bekjenne seg som buddhist.', true, true, 6),
  ('krle-9:buddhismen', 'q08', 'flervalg', 'Hvilken retning er vanligst i Sri Lanka, Thailand og Myanmar?', array['Mahayana', 'Zen', 'Tibetansk buddhisme', 'Theravada']::text[], 3, 'Theravada betyr «de eldres lære».', true, true, 7),
  ('krle-9:buddhismen', 'q09', 'flervalg', 'Hvem er leder i tibetansk buddhisme?', array['Paven', 'Keiseren av Japan', 'Dalai Lama', 'Buddha selv']::text[], 2, 'Dalai Lama fikk Nobels fredspris i 1989.', true, false, 8),
  ('krle-9:buddhismen', 'q10', 'flervalg', 'Hva feires under vesak?', array['Buddhas fødsel, oppvåkning og død', 'Nyttår', 'Innhøstingen', 'Dalai Lamas fødsel']::text[], 0, 'Vesak er den viktigste buddhistiske høytiden.', true, false, 9),
  ('krle-9:buddhismen', 'm01', 'sant-usant', 'Buddhismen oppsto for rundt 2500 år siden.', array['Sant', 'Usant']::text[], 0, 'Den oppsto i Nord-India.', false, true, 10),
  ('krle-9:buddhismen', 'm02', 'sant-usant', 'Buddhismen lærer at Buddha er en allmektig skapergud.', array['Sant', 'Usant']::text[], 1, 'Buddha regnes som et menneske som ble oppvåknet, ikke som en skapergud.', false, true, 11),
  ('krle-9:buddhismen', 'm03', 'sant-usant', 'Mindfulness har røtter i buddhistisk meditasjon.', array['Sant', 'Usant']::text[], 0, 'Mindfulness brukes i dag ofte uten religiøst innhold.', false, true, 12),
  ('krle-9:buddhismen', 'm04', 'sant-usant', 'Alle buddhister må leve som munker eller nonner.', array['Sant', 'Usant']::text[], 1, 'De fleste buddhister lever vanlige liv og støtter klostrene.', false, true, 13),
  ('krle-9:buddhismen', 'm05', 'flervalg', 'Hvor ble Siddhartha Gautama født ifølge tradisjonen?', array['Beijing', 'Lumbini i dagens Nepal', 'Tokyo', 'Colombo']::text[], 1, 'Lumbini er i dag et viktig pilegrimsmål.', false, true, 14),
  ('krle-9:buddhismen', 'm06', 'flervalg', 'Hva er sangha?', array['Et hellig tre', 'En meditasjonsform', 'En gud', 'Fellesskapet av munker, nonner og troende']::text[], 3, 'Sangha er en av de tre juvelene.', false, true, 15),
  ('krle-9:buddhismen', 'm07', 'flervalg', 'Hvilken av disse hører til den åttedelte vei?', array['Rett tale', 'Rett rikdom', 'Rett makt', 'Rett hevn']::text[], 0, 'Rett tale betyr å unngå løgn, baksnakking og sårende ord.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-9:buddhismen', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-9:religion-og-historie', 'krle-9', 'religion-og-historie', 'Religion i historiske endringer', 'Hvordan kristendom og islam har vært med på å forme historien i verden og i Norge, fra Romerriket og kristningen av Norge til reformasjonen, misjonen og skillet mellom kirke og stat.', array[2]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-9:religion-og-historie', '## Religion og endring
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-9:religion-og-historie', 'Konstantin', 'Romersk keiser som ga de kristne religionsfrihet i 313.', 0),
  ('krle-9:religion-og-historie', 'Statsreligion', 'Religion som staten har gjort offisiell. Kristendommen ble det i Romerriket i 380.', 1),
  ('krle-9:religion-og-historie', 'Kristningen av Norge', 'Overgangen fra norrøn religion til kristendom, særlig rundt år 1000.', 2),
  ('krle-9:religion-og-historie', 'Slaget på Stiklestad', 'Slaget i 1030 der Olav Haraldsson falt.', 3),
  ('krle-9:religion-og-historie', 'Olav den hellige', 'Olav Haraldsson, som ble dyrket som helgen etter sin død.', 4),
  ('krle-9:religion-og-historie', 'Nidaros', 'Trondheim, erkebispesete og et viktig pilegrimsmål i middelalderen.', 5),
  ('krle-9:religion-og-historie', 'Islams gullalder', 'Periode der byer som Bagdad var sentre for vitenskap og filosofi.', 6),
  ('krle-9:religion-og-historie', 'Algebra', 'Gren av matematikken som ble utviklet av muslimske lærde.', 7),
  ('krle-9:religion-og-historie', 'Korstogene', 'Kriger fra 1096 til 1291 for å erobre Jerusalem.', 8),
  ('krle-9:religion-og-historie', 'Reformasjonen i Norge', 'Innført i Danmark-Norge i 1537. Kongen ble kirkens overhode.', 9),
  ('krle-9:religion-og-historie', 'Misjon', 'Arbeid for å spre en religion til nye folk.', 10),
  ('krle-9:religion-og-historie', 'Det Norske Misjonsselskap', 'Norsk misjonsorganisasjon fra 1842, blant annet aktiv på Madagaskar.', 11),
  ('krle-9:religion-og-historie', 'Hans Nielsen Hauge', 'Lekpredikant som startet en vekkelse i Norge rundt 1800.', 12),
  ('krle-9:religion-og-historie', 'Dissenterloven', 'Lov fra 1845 som ga andre kristne rett til egne trossamfunn.', 13),
  ('krle-9:religion-og-historie', 'Sekularisering', 'At religion får mindre betydning i samfunnet og for den enkelte.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-9:religion-og-historie', 'q01', 'flervalg', 'Hvilken romersk keiser ga de kristne religionsfrihet i 313?', array['Nero', 'Augustus', 'Konstantin', 'Cæsar']::text[], 2, 'Etter dette vokste kristendommen raskt i Romerriket.', true, true, 0),
  ('krle-9:religion-og-historie', 'q02', 'flervalg', 'Hva skjedde på Stiklestad i 1030?', array['Olav Haraldsson falt i slag', 'Norge ble kristnet på én dag', 'Nidarosdomen sto ferdig', 'Reformasjonen startet']::text[], 0, 'Kort tid etter ble han dyrket som helgen.', true, true, 1),
  ('krle-9:religion-og-historie', 'q03', 'flervalg', 'Hvilken endring førte kristningen med seg i Norge?', array['Norrøn religion ble statsreligion', 'Runer ble den eneste skriften', 'Tingene ble avskaffet', 'Nye lover, kirker og skriftkultur']::text[], 3, 'Kirken brakte med seg latinske bokstaver, bøker og en ny organisasjon.', true, true, 2),
  ('krle-9:religion-og-historie', 'q04', 'flervalg', 'Hva bidro muslimske lærde med i islams gullalder?', array['Boktrykkerkunsten', 'Algebra og bevaring av greske tekster', 'Dampmaskinen', 'Oppdagelsen av Amerika']::text[], 1, 'Mye av den greske filosofien nådde Europa via arabiske oversettelser.', true, true, 3),
  ('krle-9:religion-og-historie', 'q05', 'flervalg', 'Når ble reformasjonen innført i Danmark-Norge?', array['1030', '1814', '1096', '1537']::text[], 3, 'Norge har vært luthersk siden da.', true, true, 4),
  ('krle-9:religion-og-historie', 'q06', 'flervalg', 'Hva var korstogene?', array['Europeiske kristnes kriger for å erobre Jerusalem', 'Misjonsreiser til Amerika', 'Pilegrimsreiser til Nidaros', 'Handelsreiser til India']::text[], 0, 'Korstogene varte fra 1096 til 1291.', true, true, 5),
  ('krle-9:religion-og-historie', 'q07', 'flervalg', 'Hva er en kritikk av misjonen i kolonitiden?', array['At den bygde skoler', 'At den ga folk sykehus', 'At den var en del av en kolonialisme som undertrykte lokale kulturer', 'At den var for liten']::text[], 2, 'Misjonen hadde både positive og negative følger for folkene den møtte.', true, true, 6),
  ('krle-9:religion-og-historie', 'q08', 'flervalg', 'Hva ga dissenterloven av 1845?', array['Forbud mot alle andre religioner', 'Andre kristne rett til å danne egne trossamfunn', 'Religionsundervisning i skolen', 'Skille mellom kirke og stat']::text[], 1, 'Loven var et viktig steg mot religionsfrihet i Norge.', true, true, 7),
  ('krle-9:religion-og-historie', 'q09', 'flervalg', 'Når ble Den norske kirke skilt fra staten som et selvstendig trossamfunn?', array['2017', '1814', '1905', '1945']::text[], 0, 'Grunnloven ble endret allerede i 2012, og skillet trådte i kraft i 2017.', true, false, 8),
  ('krle-9:religion-og-historie', 'q10', 'flervalg', 'Hvem startet en vekkelse i Norge rundt 1800?', array['Martin Luther', 'Olav Tryggvason', 'Thomas von Westen', 'Hans Nielsen Hauge']::text[], 3, 'Hauge-bevegelsen styrket også vanlige folks selvtillit og næringsliv.', true, false, 9),
  ('krle-9:religion-og-historie', 'm01', 'sant-usant', 'De første kristne ble forfulgt i Romerriket.', array['Sant', 'Usant']::text[], 0, 'Forfølgelsen tok slutt da Konstantin ga dem religionsfrihet i 313.', false, true, 10),
  ('krle-9:religion-og-historie', 'm02', 'sant-usant', 'Kristningen av Norge skjedde helt fredelig.', array['Sant', 'Usant']::text[], 1, 'Kongene brukte ofte makt og tvang for å kristne folket.', false, true, 11),
  ('krle-9:religion-og-historie', 'm03', 'sant-usant', 'Etter reformasjonen ble kongen overhode for kirken i Danmark-Norge.', array['Sant', 'Usant']::text[], 0, 'Paven mistet all makt over kirken i Norge.', false, true, 12),
  ('krle-9:religion-og-historie', 'm04', 'sant-usant', 'Religion har bare ført til konflikter og aldri til positiv endring.', array['Sant', 'Usant']::text[], 1, 'Religion har også inspirert kamp for rettferdighet, utdanning og omsorg.', false, true, 13),
  ('krle-9:religion-og-historie', 'm05', 'flervalg', 'Hvilken by ble et viktig pilegrimsmål etter Olav den hellige?', array['Bergen', 'Oslo', 'Nidaros (Trondheim)', 'Stavanger']::text[], 2, 'Olav ble gravlagt i Nidaros, der Nidarosdomen senere ble bygd.', false, true, 14),
  ('krle-9:religion-og-historie', 'm06', 'flervalg', 'Hvor drev Det Norske Misjonsselskap blant annet misjon?', array['Island', 'Madagaskar', 'Grønland', 'Sicilia']::text[], 1, 'Misjonsselskapet var også aktivt i Sør-Afrika.', false, true, 15),
  ('krle-9:religion-og-historie', 'm07', 'flervalg', 'Hva er sekularisering?', array['At religion får mindre betydning i samfunnet', 'At det bygges flere kirker', 'At staten får en ny religion', 'At flere går i kirken']::text[], 0, 'Sekularisering har preget Norge og mange andre land de siste hundre årene.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-9:religion-og-historie', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-9:religiost-mangfold', 'krle-9', 'religiost-mangfold', 'Religiøst mangfold og nyreligiøsitet', 'Det religiøse landskapet i Norge, nyreligiøsitet og alternativ spiritualitet, nye religiøse bevegelser, folkereligiøsitet og sivilreligion, og hvordan du kan vurdere slike praksiser kritisk.', array[4]::int[], 3, 'sjekkes', array['Andelen medlemmer i Den norske kirke (rundt 60 prosent) bør sjekkes mot ferske tall fra SSB.']::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-9:religiost-mangfold', '## Et mangfoldig religiøst landskap
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-9:religiost-mangfold', 'Religiøst mangfold', 'At mange ulike religioner og livssyn finnes side om side i et samfunn.', 0),
  ('krle-9:religiost-mangfold', 'Tros- og livssynssamfunn', 'Organisert fellesskap for en religion eller et livssyn.', 1),
  ('krle-9:religiost-mangfold', 'Nyreligiøsitet', 'Tro og praksiser som blander elementer fra ulike tradisjoner og vektlegger egen erfaring.', 2),
  ('krle-9:religiost-mangfold', 'Alternativ spiritualitet', 'Annet ord for nyreligiøsitet, for eksempel healing, astrologi og engletro.', 3),
  ('krle-9:religiost-mangfold', 'Healing', 'Tro på at energier eller håndspåleggelse kan helbrede.', 4),
  ('krle-9:religiost-mangfold', 'Astrologi', 'Troen på at stjernenes og planetenes stilling påvirker livet vårt.', 5),
  ('krle-9:religiost-mangfold', 'Reinkarnasjon', 'Troen på at sjelen blir født på nytt i en ny kropp.', 6),
  ('krle-9:religiost-mangfold', 'Privatreligiøsitet', 'At den enkelte selv velger og setter sammen det hun eller han tror på.', 7),
  ('krle-9:religiost-mangfold', 'Mindfulness', 'Oppmerksomhetstrening med røtter i buddhistisk meditasjon.', 8),
  ('krle-9:religiost-mangfold', 'St. Olavsleden', 'Pilegrimsled til Nidaros som er blitt populær igjen.', 9),
  ('krle-9:religiost-mangfold', 'Åsatro', 'Norrøn tro som har fått nye tilhengere i vår tid.', 10),
  ('krle-9:religiost-mangfold', 'Nye religiøse bevegelser', 'Bevegelser fra de siste 200 årene, som Jehovas vitner og bahá''í.', 11),
  ('krle-9:religiost-mangfold', 'Folkereligiøsitet', 'Religiøse vaner og overtro i hverdagen, som å banke i bordet.', 12),
  ('krle-9:religiost-mangfold', 'Sivilreligion', 'Ritualer og symboler som samler et folk, som 17. mai.', 13),
  ('krle-9:religiost-mangfold', 'Lov om alternativ behandling', 'Norsk lov som regulerer hva utøvere av alternativ behandling har lov til.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-9:religiost-mangfold', 'q01', 'flervalg', 'Hva er nyreligiøsitet?', array['En ny kristen kirke', 'Tro og praksiser som blander elementer fra ulike tradisjoner og vektlegger egen erfaring', 'En type ateisme', 'Et politisk parti']::text[], 1, 'Nyreligiøsitet kalles også alternativ spiritualitet.', true, true, 0),
  ('krle-9:religiost-mangfold', 'q02', 'flervalg', 'Hva er et eksempel på alternativ spiritualitet?', array['Nattverd', 'Fredagsbønn', 'Sabbat', 'Healing med energier']::text[], 3, 'De andre er praksiser i etablerte religioner.', true, true, 1),
  ('krle-9:religiost-mangfold', 'q03', 'flervalg', 'Hva er privatreligiøsitet?', array['At man selv velger og setter sammen det man tror på', 'At man ber alene i kirken', 'At religion er forbudt', 'At staten bestemmer religion']::text[], 0, 'Mange henter elementer fra flere tradisjoner.', true, true, 2),
  ('krle-9:religiost-mangfold', 'q04', 'flervalg', 'Hvilken praksis har røtter i buddhismen, men brukes ofte uten religiøst innhold?', array['Nattverd', 'Faste i ramadan', 'Mindfulness', 'Omskjæring']::text[], 2, 'Mindfulness brukes blant annet i skoler og helsevesen.', true, true, 3),
  ('krle-9:religiost-mangfold', 'q05', 'flervalg', 'Hva er St. Olavsleden?', array['En gammel handelsvei til Sverige', 'En skiløype', 'En pilegrimsled til Nidaros', 'En kirke i Oslo']::text[], 2, 'Pilegrimsvandring har fått en ny oppblomstring de siste tiårene.', true, true, 4),
  ('krle-9:religiost-mangfold', 'q06', 'flervalg', 'Hva er åsatro?', array['En buddhistisk retning', 'Norrøn tro som har fått nye tilhengere', 'En type yoga', 'En katolsk orden']::text[], 1, 'Noen åsatrusamfunn er registrerte trossamfunn i Norge.', true, true, 5),
  ('krle-9:religiost-mangfold', 'q07', 'flervalg', 'Hva er sivilreligion?', array['En religion for sivile, ikke soldater', 'En ny religiøs bevegelse', 'Religion i privatlivet', 'Ritualer og symboler som samler et folk, som 17. mai']::text[], 3, 'Sivilreligion viser seg også i minnemarkeringer etter nasjonale tragedier.', true, true, 6),
  ('krle-9:religiost-mangfold', 'q08', 'flervalg', 'Hvilken av disse er en ny religiøs bevegelse?', array['Jehovas vitner', 'Den katolske kirke', 'Sunni-islam', 'Ortodoks jødedom']::text[], 0, 'Jehovas vitner oppsto i USA på 1870-tallet.', true, true, 7),
  ('krle-9:religiost-mangfold', 'q09', 'flervalg', 'Hvorfor er det viktig å være kritisk til noen alternative behandlingsformer?', array['Fordi all tro er feil', 'Fordi noen hevder å kunne kurere sykdommer uten dokumentasjon', 'Fordi de er forbudt', 'Fordi de alltid er dyre']::text[], 1, 'Å velge bort vanlig behandling kan være farlig ved alvorlig sykdom.', true, false, 8),
  ('krle-9:religiost-mangfold', 'q10', 'flervalg', 'Hva er et eksempel på folkereligiøsitet?', array['Å konfirmere seg', 'Å gå i moskeen', 'Å lese Koranen', 'Å banke i bordet for å unngå uhell']::text[], 3, 'Folkereligiøse vaner følges ofte uten at man tenker over dem.', true, false, 9),
  ('krle-9:religiost-mangfold', 'm01', 'sant-usant', 'Mange i Norge praktiserer noe religiøst utenfor de etablerte religionssamfunnene.', array['Sant', 'Usant']::text[], 0, 'For eksempel healing, astrologi, meditasjon eller pilegrimsvandring.', false, true, 10),
  ('krle-9:religiost-mangfold', 'm02', 'sant-usant', 'Yoga kan bare praktiseres av hinduer.', array['Sant', 'Usant']::text[], 1, 'Yoga har røtter i hinduismen, men praktiseres av mange uten religiøst innhold.', false, true, 11),
  ('krle-9:religiost-mangfold', 'm03', 'sant-usant', 'Religionsfriheten gir alle rett til å tro på det de vil.', array['Sant', 'Usant']::text[], 0, 'Religionsfrihet er en menneskerettighet.', false, true, 12),
  ('krle-9:religiost-mangfold', 'm04', 'sant-usant', 'Nyreligiøsitet legger vanligvis mest vekt på en felles, fast lære.', array['Sant', 'Usant']::text[], 1, 'Nyreligiøsitet vektlegger som regel den enkeltes erfaring og valg.', false, true, 13),
  ('krle-9:religiost-mangfold', 'm05', 'flervalg', 'Hva er reinkarnasjon?', array['Troen på at sjelen blir født på nytt', 'Troen på engler', 'En type healing', 'Troen på én Gud']::text[], 0, 'Ideen finnes blant annet i hinduisme og buddhisme, og hos mange nyreligiøse.', false, true, 14),
  ('krle-9:religiost-mangfold', 'm06', 'flervalg', 'Hva er astrologi?', array['Vitenskapen om stjerner og planeter', 'Troen på at stjernenes og planetenes stilling påvirker livet vårt', 'En type meditasjon', 'En pilegrimsreise']::text[], 1, 'Vitenskapen om himmellegemene heter astronomi.', false, true, 15),
  ('krle-9:religiost-mangfold', 'm07', 'flervalg', 'Hva regulerer lov om alternativ behandling?', array['Hvem som kan bli prest', 'Hvilke høytider som er fridager', 'Hva utøvere av alternativ behandling har lov til', 'Hvor mange trossamfunn det kan være']::text[], 2, 'Loven skal beskytte pasienter, særlig ved alvorlig sykdom.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-9:religiost-mangfold', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-9:religion-i-populaerkultur', 'krle-9', 'religion-i-populaerkultur', 'Religion i medier og populærkultur', 'Hvordan elementer fra kristendom og andre religioner og livssyn dukker opp i film, serier, musikk, spill og reklame, og hvordan religion framstilles og debatteres i mediene.', array[9]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-9:religion-i-populaerkultur', '## Religion overalt
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-9:religion-i-populaerkultur', 'Populærkultur', 'Kultur som når mange, som film, serier, musikk, spill og reklame.', 0),
  ('krle-9:religion-i-populaerkultur', 'Kristusfigur', 'Person i en fortelling som ofrer seg for andre og kommer tilbake.', 1),
  ('krle-9:religion-i-populaerkultur', 'Aslan', 'Løven i Narnia, en tydelig Kristusfigur.', 2),
  ('krle-9:religion-i-populaerkultur', 'The Matrix', 'Film med frelserfiguren Neo og ideen om at verden er en illusjon.', 3),
  ('krle-9:religion-i-populaerkultur', 'Kraften i Star Wars', 'Ide som minner om buddhisme og daoisme, med meditasjon og balanse.', 4),
  ('krle-9:religion-i-populaerkultur', 'Norrøn mytologi i film', 'Brukes blant annet i Marvel-filmene om Thor og i serien Ragnarok.', 5),
  ('krle-9:religion-i-populaerkultur', 'Sana i Skam', 'Muslimsk hovedperson som fikk ros for en nyansert framstilling.', 6),
  ('krle-9:religion-i-populaerkultur', 'Gospel', 'Kristen musikk som vokste fram blant svarte kristne i USA.', 7),
  ('krle-9:religion-i-populaerkultur', 'Spirituals', 'Religiøse sanger fra slaveriets tid i USA, forløperen til gospel.', 8),
  ('krle-9:religion-i-populaerkultur', 'Religiøse symboler i reklame', 'Engler, glorier og «himmelsk» brukes for å gi produkter et rent og godt preg.', 9),
  ('krle-9:religion-i-populaerkultur', 'Satire', 'Humor og kritikk som gjør narr av noe.', 10),
  ('krle-9:religion-i-populaerkultur', 'Life of Brian', 'Film fra 1979 som vakte sterke reaksjoner for måten den behandlet religion på.', 11),
  ('krle-9:religion-i-populaerkultur', 'Muhammed-tegningene', 'Tegninger fra 2005 som førte til protester og debatt om ytringsfrihet og respekt.', 12),
  ('krle-9:religion-i-populaerkultur', 'Blasfemiparagrafen', 'Tidligere bestemmelse som forbød å håne religion. Den er fjernet fra straffeloven.', 13),
  ('krle-9:religion-i-populaerkultur', 'Stereotypi', 'Forenklet bilde av en gruppe, for eksempel av troende i en religion.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-9:religion-i-populaerkultur', 'q01', 'flervalg', 'Hva er en Kristusfigur i en film?', array['En skuespiller som spiller Jesus', 'En prest i en film', 'En figur som alltid er ond', 'En person som ofrer seg for andre og kommer tilbake']::text[], 3, 'Figuren trenger ikke være religiøs, men ligner Jesus i det den gjør.', true, true, 0),
  ('krle-9:religion-i-populaerkultur', 'q02', 'flervalg', 'Hvilken figur i Narnia regnes som en tydelig Kristusfigur?', array['Løven Aslan', 'Den hvite heksa', 'Faunen Tumnus', 'Peter']::text[], 0, 'Aslan ofrer livet for Edmund og står opp igjen.', true, true, 1),
  ('krle-9:religion-i-populaerkultur', 'q03', 'flervalg', 'Hvilken mytologi bygger Marvel-filmene om Thor på?', array['Gresk', 'Egyptisk', 'Norrøn', 'Romersk']::text[], 2, 'Tor var tordenguden i norrøn religion.', true, true, 2),
  ('krle-9:religion-i-populaerkultur', 'q04', 'flervalg', 'Hvor vokste gospel og spirituals fram?', array['Blant munker i Europa', 'Blant svarte kristne i USA', 'I norske bedehus', 'I India']::text[], 1, 'Musikken har påvirket soul, rock og pop.', true, true, 3),
  ('krle-9:religion-i-populaerkultur', 'q05', 'flervalg', 'Hvilken religiøs idé bruker The Matrix blant annet?', array['At verden vi ser, er en illusjon', 'At man skal faste i ramadan', 'At sabbaten er hellig', 'At kua er hellig']::text[], 0, 'Ideen finnes blant annet i hinduisme og buddhisme.', true, true, 4),
  ('krle-9:religion-i-populaerkultur', 'q06', 'flervalg', 'Hvorfor bruker reklame ofte engler og glorier?', array['Fordi det er påbudt', 'Fordi alle kunder er religiøse', 'For å gjøre produktet dyrere', 'For å gi produktet et preg av noe rent og godt']::text[], 3, 'Religiøse symboler har sterke assosiasjoner som reklamen utnytter.', true, true, 5),
  ('krle-9:religion-i-populaerkultur', 'q07', 'flervalg', 'Hvilke spørsmål reiste Muhammed-tegningene i 2005?', array['Spørsmål om skatt og avgifter', 'Spørsmål om ytringsfrihet og respekt for andres tro', 'Spørsmål om klimaendringer', 'Spørsmål om skolemat']::text[], 1, 'Saken skapte debatt og protester i mange land.', true, true, 6),
  ('krle-9:religion-i-populaerkultur', 'q08', 'flervalg', 'Hva var blasfemiparagrafen?', array['En regel om julefeiring', 'En lov om kirkebygg', 'En bestemmelse som forbød å håne religion', 'En lov om religionsfrihet']::text[], 2, 'Bestemmelsen er fjernet fra straffeloven.', true, true, 7),
  ('krle-9:religion-i-populaerkultur', 'q09', 'flervalg', 'Hvorfor fikk serien Skam ros for karakteren Sana?', array['Fordi hun viste en ung muslim på en nyansert måte', 'Fordi hun var skurken', 'Fordi hun var prest', 'Fordi hun ikke hadde noen religion']::text[], 0, 'Mange mente serien motvirket stereotypier om muslimer.', true, false, 8),
  ('krle-9:religion-i-populaerkultur', 'q10', 'flervalg', 'Hvilket spørsmål er nyttig når du analyserer religion i en film?', array['Hvor lang er filmen?', 'Hvor mye kostet billetten?', 'Hvordan framstilles de troende?', 'Hvem er vennene til skuespillerne?']::text[], 2, 'Framstillingen kan påvirke hvordan seerne ser på en religion.', true, false, 9),
  ('krle-9:religion-i-populaerkultur', 'm01', 'sant-usant', 'Kunnskap om religion gjør det lettere å forstå referanser i film og musikk.', array['Sant', 'Usant']::text[], 0, 'Mange fortellinger låner motiver fra religiøse tekster.', false, true, 10),
  ('krle-9:religion-i-populaerkultur', 'm02', 'sant-usant', 'Det er forbudt å lage satire om religion i Norge.', array['Sant', 'Usant']::text[], 1, 'Satire om religion er lov, men hatefulle ytringer mot mennesker er forbudt.', false, true, 11),
  ('krle-9:religion-i-populaerkultur', 'm03', 'sant-usant', 'Hatefulle ytringer mot mennesker på grunn av religion er forbudt i Norge.', array['Sant', 'Usant']::text[], 0, 'Straffeloven verner mennesker, ikke religioner som sådan.', false, true, 12),
  ('krle-9:religion-i-populaerkultur', 'm04', 'sant-usant', 'Religiøse symboler brukes bare av religiøse mennesker.', array['Sant', 'Usant']::text[], 1, 'Kors og andre symboler brukes også som mote og i reklame.', false, true, 13),
  ('krle-9:religion-i-populaerkultur', 'm05', 'flervalg', 'Hvilke religiøse tradisjoner minner Kraften og jediene i Star Wars om?', array['Islam', 'Jødedom', 'Buddhisme og daoisme', 'Norrøn religion']::text[], 2, 'Jediene mediterer og søker balanse, omtrent som munker.', false, true, 14),
  ('krle-9:religion-i-populaerkultur', 'm06', 'flervalg', 'Hva er satire?', array['Humor og kritikk som gjør narr av noe', 'En type bønn', 'En hellig tekst', 'En religiøs høytid']::text[], 0, 'Satire er en gammel form for samfunnskritikk.', false, true, 15),
  ('krle-9:religion-i-populaerkultur', 'm07', 'flervalg', 'Hvilken film fra 1979 vakte sterke reaksjoner for måten den behandlet religion på?', array['Star Wars', 'Life of Brian', 'Løvenes konge', 'Titanic']::text[], 1, 'Filmen ble en tid forbudt i flere land, blant annet i Norge.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-9:religion-i-populaerkultur', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-9:etiske-forbilder', 'krle-9', 'etiske-forbilder', 'Etiske forbilder i religioner og livssyn', 'Etiske ideer fra Jesus, Muhammad, Buddha, Hillel og Konfutse, moderne forbilder som Gandhi, Martin Luther King og Desmond Tutu, og likheter og forskjeller mellom dem.', array[10]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-9:etiske-forbilder', '## Forbilder i etikken
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-9:etiske-forbilder', 'Nestekjærlighet', 'Jesu bud om å elske sin neste som seg selv.', 0),
  ('krle-9:etiske-forbilder', 'Bergprekenen', 'Jesu tale der han blant annet sier «Elsk deres fiender».', 1),
  ('krle-9:etiske-forbilder', 'Den barmhjertige samaritan', 'Lignelse som viser at nesten er den som trenger hjelp, uansett hvem det er.', 2),
  ('krle-9:etiske-forbilder', 'Den gylne regel', 'Gjør mot andre det du vil at de skal gjøre mot deg. Finnes i mange tradisjoner.', 3),
  ('krle-9:etiske-forbilder', 'Barmhjertighet i islam', 'Muhammad la vekt på omsorg for fattige, enker og foreldreløse.', 4),
  ('krle-9:etiske-forbilder', 'Medfølelse', 'Å føle med og ville hjelpe andre som lider. Sentralt i buddhismen.', 5),
  ('krle-9:etiske-forbilder', 'De fem forskriftene', 'Buddhistiske regler: ikke drepe, stjele, lyve, misbruke seksualitet eller ruse seg.', 6),
  ('krle-9:etiske-forbilder', 'Hillel', 'Jødisk lærer: «Det som er hatefullt for deg, skal du ikke gjøre mot din neste.»', 7),
  ('krle-9:etiske-forbilder', 'Konfutse', 'Kinesisk filosof som vektla respekt, gode relasjoner og gode ledere.', 8),
  ('krle-9:etiske-forbilder', 'Ahimsa', 'Ikkevold. Sentralt i hinduisme, buddhisme og for Gandhi.', 9),
  ('krle-9:etiske-forbilder', 'Mahatma Gandhi', 'Ledet Indias kamp for selvstendighet med ikkevold.', 10),
  ('krle-9:etiske-forbilder', 'Martin Luther King', 'Baptistprest som ledet ikkevoldelig kamp mot rasisme i USA.', 11),
  ('krle-9:etiske-forbilder', 'Mor Teresa', 'Katolsk nonne som stelte syke og døende i Kolkata. Fredsprisen 1979.', 12),
  ('krle-9:etiske-forbilder', 'Desmond Tutu', 'Anglikansk erkebiskop som kjempet mot apartheid og for forsoning.', 13),
  ('krle-9:etiske-forbilder', 'Ubuntu', 'Sørafrikansk tanke: «Jeg er fordi vi er.»', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-9:etiske-forbilder', 'q01', 'flervalg', 'Hva lærer lignelsen om den barmhjertige samaritan?', array['At man bare skal hjelpe familien', 'At nesten er den som trenger hjelp, uansett hvem det er', 'At man skal gå i tempelet', 'At samaritanere var onde']::text[], 1, 'Samaritanen hjalp en fremmed som andre hadde gått forbi.', true, true, 0),
  ('krle-9:etiske-forbilder', 'q02', 'flervalg', 'Hvilken lærer sa: «Det som er hatefullt for deg, skal du ikke gjøre mot din neste»?', array['Buddha', 'Gandhi', 'Muhammad', 'Hillel']::text[], 3, 'Hillel mente at dette var kjernen i hele Toraen.', true, true, 1),
  ('krle-9:etiske-forbilder', 'q03', 'flervalg', 'Hva betyr ahimsa?', array['Medfølelse', 'Sannhet', 'Ikkevold', 'Plikt']::text[], 2, 'Ahimsa var grunnlaget for Gandhis kamp.', true, true, 2),
  ('krle-9:etiske-forbilder', 'q04', 'flervalg', 'Hvem stelte syke og døende i Kolkata og fikk Nobels fredspris i 1979?', array['Mor Teresa', 'Dalai Lama', 'Desmond Tutu', 'Malala Yousafzai']::text[], 0, 'Hun grunnla en orden som arbeider blant de fattigste.', true, true, 3),
  ('krle-9:etiske-forbilder', 'q05', 'flervalg', 'Hva er et fellestrekk ved mange religiøse og livssynsbaserte tradisjoner?', array['At de har samme gud', 'At de har samme matregler', 'At de har samme høytider', 'At de har en variant av den gylne regel']::text[], 3, 'Varianter av regelen finnes hos Jesus, Hillel, Konfutse og mange andre.', true, true, 4),
  ('krle-9:etiske-forbilder', 'q06', 'flervalg', 'Hvem bygde på Gandhis metoder i kampen mot rasisme i USA?', array['Desmond Tutu', 'Martin Luther King', 'Konfutse', 'Hillel']::text[], 1, 'King kombinerte Jesu kjærlighetsbud med Gandhis ikkevold.', true, true, 5),
  ('krle-9:etiske-forbilder', 'q07', 'flervalg', 'Hva betyr ubuntu?', array['«Jeg er fordi vi er»', '«Elsk deres fiender»', '«Ingen vold»', '«Følg middelveien»']::text[], 0, 'Ubuntu understreker at mennesker henger sammen og trenger hverandre.', true, true, 6),
  ('krle-9:etiske-forbilder', 'q08', 'flervalg', 'Hva sa Jesus i Bergprekenen om fiender?', array['At man skal hevne seg', 'At man skal unngå dem', 'At man skal elske dem', 'At man skal frykte dem']::text[], 2, 'Budet om å elske fiendene var radikalt i sin samtid.', true, true, 7),
  ('krle-9:etiske-forbilder', 'q09', 'flervalg', 'Hvordan kan begrunnelsen for etikk være forskjellig i ulike tradisjoner?', array['Den er alltid den samme', 'Alle viser til karma', 'Alle viser til fornuft', 'Noen viser til Guds bud, andre til karma eller fornuft']::text[], 3, 'Tradisjoner kan komme fram til like regler av ulike grunner.', true, false, 8),
  ('krle-9:etiske-forbilder', 'q10', 'flervalg', 'Hvilken islamsk plikt handler om å hjelpe fattige?', array['Hajj', 'Zakat', 'Salat', 'Shahada']::text[], 1, 'Zakat er en av islams fem søyler.', true, false, 9),
  ('krle-9:etiske-forbilder', 'm01', 'sant-usant', 'Konfutse levde flere hundre år før Jesus.', array['Sant', 'Usant']::text[], 0, 'Konfutse levde på 500-tallet før vår tidsregning.', false, true, 10),
  ('krle-9:etiske-forbilder', 'm02', 'sant-usant', 'Gandhi ledet Indias kamp for selvstendighet gjennom væpnet opprør.', array['Sant', 'Usant']::text[], 1, 'Gandhi brukte ikkevold, som marsjer, boikott og sivil ulydighet.', false, true, 11),
  ('krle-9:etiske-forbilder', 'm03', 'sant-usant', 'Desmond Tutu la vekt på forsoning etter apartheid.', array['Sant', 'Usant']::text[], 0, 'Han ledet Sannhets- og forsoningskommisjonen i Sør-Afrika.', false, true, 12),
  ('krle-9:etiske-forbilder', 'm04', 'sant-usant', 'Alle religioner begrunner etikken på nøyaktig samme måte.', array['Sant', 'Usant']::text[], 1, 'Begrunnelsene varierer, selv om reglene ofte ligner.', false, true, 13),
  ('krle-9:etiske-forbilder', 'm05', 'flervalg', 'Hva sier de buddhistiske forskriftene blant annet?', array['At man skal be fem ganger om dagen', 'At man ikke skal drepe, stjele eller lyve', 'At man skal holde sabbaten', 'At man skal gi bort alt man eier']::text[], 1, 'Forskriftene gjelder alle buddhister, ikke bare munker.', false, true, 14),
  ('krle-9:etiske-forbilder', 'm06', 'flervalg', 'Hvem er den kjente lederen i tibetansk buddhisme som har gjort medfølelse kjent i verden?', array['Dalai Lama', 'Konfutse', 'Hillel', 'Mor Teresa']::text[], 0, 'Dalai Lama fikk Nobels fredspris i 1989.', false, true, 15),
  ('krle-9:etiske-forbilder', 'm07', 'flervalg', 'Hvorfor kan det være nyttig å skille mellom ideene og personen når vi ser på forbilder?', array['Fordi forbilder aldri tar feil', 'Fordi ideer ikke betyr noe', 'Fordi forbilder også er mennesker som kan ha gjort feil', 'Fordi personer ikke betyr noe']::text[], 2, 'Gode ideer kan ha verdi selv om personen bak dem har svakheter.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-9:etiske-forbilder', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('tysk-9:mat-og-drikke', 'tysk-9', 'mat-og-drikke', 'Mat og drikke', 'Måltider, mat og drikke på tysk, hvordan du sier hva du liker, hvordan du bestiller på kafé og restaurant, og akkusativ med den og einen.', array[2, 4]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('tysk-9:mat-og-drikke', '## Måltider – die Mahlzeiten
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('tysk-9:mat-og-drikke', 'das Frühstück', 'frokosten', 0),
  ('tysk-9:mat-og-drikke', 'das Mittagessen', 'måltidet midt på dagen', 1),
  ('tysk-9:mat-og-drikke', 'das Abendbrot', 'kveldsmaten, ofte brød med pålegg', 2),
  ('tysk-9:mat-og-drikke', 'das Brötchen', 'rundstykket', 3),
  ('tysk-9:mat-og-drikke', 'der Käse', 'osten', 4),
  ('tysk-9:mat-og-drikke', 'die Wurst', 'pølsa, også pølsepålegg', 5),
  ('tysk-9:mat-og-drikke', 'das Obst', 'frukt', 6),
  ('tysk-9:mat-og-drikke', 'das Gemüse', 'grønnsaker', 7),
  ('tysk-9:mat-og-drikke', 'das Hähnchen', 'kyllingen', 8),
  ('tysk-9:mat-og-drikke', 'der Saft', 'juicen', 9),
  ('tysk-9:mat-og-drikke', 'Ich habe Hunger.', 'Jeg er sulten.', 10),
  ('tysk-9:mat-og-drikke', 'Ich möchte …', 'Jeg vil gjerne ha …', 11),
  ('tysk-9:mat-og-drikke', 'die Speisekarte', 'menyen', 12),
  ('tysk-9:mat-og-drikke', 'Die Rechnung, bitte!', 'Regningen, takk!', 13),
  ('tysk-9:mat-og-drikke', 'Guten Appetit!', 'God appetitt!', 14),
  ('tysk-9:mat-og-drikke', 'essen: du isst, er isst', 'å spise – uregelrett i entall', 15);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('tysk-9:mat-og-drikke', 'q01', 'flervalg', 'Hva betyr «das Frühstück»?', array['Middag', 'Lunsj', 'Frokost', 'Kveldsmat']::text[], 2, '«früh» betyr tidlig.', true, true, 0),
  ('tysk-9:mat-og-drikke', 'q02', 'flervalg', 'Hvordan sier du «Jeg er sulten»?', array['Ich habe Hunger.', 'Ich bin Hunger.', 'Ich habe Durst.', 'Ich esse Hunger.']::text[], 0, 'På tysk «har» man sult.', true, true, 1),
  ('tysk-9:mat-og-drikke', 'q03', 'flervalg', 'Hva er riktig form av «essen» med «du»?', array['du esse', 'du essen', 'du esst', 'du isst']::text[], 3, '«essen» bytter vokal i entall: du isst, er isst.', true, true, 2),
  ('tysk-9:mat-og-drikke', 'q04', 'flervalg', 'Hvordan bestiller du høflig en te?', array['Ich will Tee!', 'Ich möchte einen Tee, bitte.', 'Tee jetzt!', 'Du Tee?']::text[], 1, '«Ich möchte …, bitte» er høflig.', true, true, 3),
  ('tysk-9:mat-og-drikke', 'q05', 'flervalg', 'Hvordan ber du om regningen?', array['Guten Appetit!', 'Prost!', 'Die Speisekarte, bitte.', 'Die Rechnung, bitte.']::text[], 3, 'Du kan også si «Zahlen, bitte!».', true, true, 4),
  ('tysk-9:mat-og-drikke', 'q06', 'flervalg', 'Hva er «das Obst»?', array['Grønnsaker', 'Kjøtt', 'Frukt', 'Brød']::text[], 2, 'Grønnsaker heter «das Gemüse».', true, true, 5),
  ('tysk-9:mat-og-drikke', 'q07', 'flervalg', 'Hvilken setning er riktig?', array['Ich möchte ein Apfel.', 'Ich möchte einen Apfel.', 'Ich möchte eine Apfel.', 'Ich möchte einer Apfel.']::text[], 1, '«Apfel» er hankjønn og står som objekt, derfor «einen».', true, true, 6),
  ('tysk-9:mat-og-drikke', 'q08', 'flervalg', 'Hva sier du før måltidet?', array['Guten Appetit!', 'Auf Wiedersehen!', 'Zahlen, bitte!', 'Gute Nacht!']::text[], 0, 'Det betyr «God appetitt!».', true, true, 7),
  ('tysk-9:mat-og-drikke', 'q09', 'flervalg', 'Hva er «das Abendbrot» i mange tyske familier?', array['En varm middag', 'Kake', 'Frokost', 'Et kveldsmåltid med brød og pålegg']::text[], 3, 'Ordet betyr bokstavelig «kveldsbrød».', true, false, 8),
  ('tysk-9:mat-og-drikke', 'q10', 'flervalg', 'Hva betyr «die Speisekarte»?', array['Regningen', 'Bordet', 'Menyen', 'Kokken']::text[], 2, '«Speise» betyr rett eller mat.', true, false, 9),
  ('tysk-9:mat-og-drikke', 'm01', 'sant-usant', '«Ich habe Durst» betyr jeg er tørst.', array['Sant', 'Usant']::text[], 0, '«Durst» betyr tørst.', false, true, 10),
  ('tysk-9:mat-og-drikke', 'm02', 'sant-usant', '«das Gemüse» betyr frukt.', array['Sant', 'Usant']::text[], 1, '«das Gemüse» betyr grønnsaker. Frukt heter «das Obst».', false, true, 11),
  ('tysk-9:mat-og-drikke', 'm03', 'sant-usant', 'I Tyskland er det vanlig å runde opp eller gi litt tips på restaurant.', array['Sant', 'Usant']::text[], 0, 'Tips kalles «Trinkgeld».', false, true, 12),
  ('tysk-9:mat-og-drikke', 'm04', 'sant-usant', '«nehmen» bøyes «du nehmst».', array['Sant', 'Usant']::text[], 1, 'Det heter «du nimmst» og «er nimmt».', false, true, 13),
  ('tysk-9:mat-og-drikke', 'm05', 'flervalg', 'Hva betyr «Ich mag keinen Fisch»?', array['Jeg liker fisk', 'Jeg liker ikke fisk', 'Jeg har fisk', 'Jeg spiser fisk i dag']::text[], 1, '«kein» nekter substantivet.', false, true, 14),
  ('tysk-9:mat-og-drikke', 'm06', 'flervalg', 'Hva er «das Brötchen»?', array['Et rundstykke', 'En kake', 'En pølse', 'Et egg']::text[], 0, 'Endelsen -chen betyr at noe er lite: et lite brød.', false, true, 15),
  ('tysk-9:mat-og-drikke', 'm07', 'flervalg', 'Hva sier man når man skåler?', array['Guten Appetit!', 'Danke!', 'Prost!', 'Tschüs!']::text[], 2, '«Prost!» betyr «Skål!».', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('tysk-9:mat-og-drikke', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('tysk-9:hjemmet-og-hverdagen', 'tysk-9', 'hjemmet-og-hverdagen', 'Hjemmet og hverdagen', 'Rom og møbler på tysk, hvordan du beskriver rommet ditt og en vanlig dag, delbare og refleksive verb, og ord som hjelper deg å fortelle i rekkefølge.', array[3, 5]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('tysk-9:hjemmet-og-hverdagen', '## Hjemmet – das Zuhause
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('tysk-9:hjemmet-og-hverdagen', 'die Wohnung', 'leiligheten', 0),
  ('tysk-9:hjemmet-og-hverdagen', 'das Zimmer', 'rommet', 1),
  ('tysk-9:hjemmet-og-hverdagen', 'die Küche', 'kjøkkenet', 2),
  ('tysk-9:hjemmet-og-hverdagen', 'das Wohnzimmer', 'stua', 3),
  ('tysk-9:hjemmet-og-hverdagen', 'das Schlafzimmer', 'soverommet', 4),
  ('tysk-9:hjemmet-og-hverdagen', 'das Badezimmer', 'badet', 5),
  ('tysk-9:hjemmet-og-hverdagen', 'der Schrank', 'skapet', 6),
  ('tysk-9:hjemmet-og-hverdagen', 'der Schreibtisch', 'skrivebordet', 7),
  ('tysk-9:hjemmet-og-hverdagen', 'gemütlich', 'koselig', 8),
  ('tysk-9:hjemmet-og-hverdagen', 'aufstehen – Ich stehe auf.', 'å stå opp – Jeg står opp.', 9),
  ('tysk-9:hjemmet-og-hverdagen', 'fernsehen – Ich sehe fern.', 'å se på TV – Jeg ser på TV.', 10),
  ('tysk-9:hjemmet-og-hverdagen', 'aufräumen', 'å rydde', 11),
  ('tysk-9:hjemmet-og-hverdagen', 'sich duschen – Ich dusche mich.', 'å dusje – Jeg dusjer.', 12),
  ('tysk-9:hjemmet-og-hverdagen', 'Hausaufgaben machen', 'å gjøre lekser', 13),
  ('tysk-9:hjemmet-og-hverdagen', 'zuerst, dann, danach', 'først, så, etterpå', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('tysk-9:hjemmet-og-hverdagen', 'q01', 'flervalg', 'Hva betyr «die Wohnung»?', array['Huset', 'Leiligheten', 'Rommet', 'Hagen']::text[], 1, '«wohnen» betyr å bo.', true, true, 0),
  ('tysk-9:hjemmet-og-hverdagen', 'q02', 'flervalg', 'Hvor lager man mat?', array['im Schlafzimmer', 'im Badezimmer', 'im Keller', 'in der Küche']::text[], 3, '«die Küche» betyr kjøkkenet.', true, true, 1),
  ('tysk-9:hjemmet-og-hverdagen', 'q03', 'flervalg', 'Hvordan sier du «Jeg står opp klokka sju»?', array['Ich stehe um sieben Uhr auf.', 'Ich aufstehe um sieben Uhr.', 'Ich stehe auf um sieben Uhr auf.', 'Um sieben Uhr ich stehe auf.']::text[], 0, 'Forstavelsen «auf» flyttes til slutten.', true, true, 2),
  ('tysk-9:hjemmet-og-hverdagen', 'q04', 'flervalg', 'Hva skjer med forstavelsen i et delbart verb som «fernsehen»?', array['Den forsvinner', 'Den står først', 'Den flyttes til slutten av setningen', 'Den dobles']::text[], 2, '«Ich sehe am Abend fern.»', true, true, 3),
  ('tysk-9:hjemmet-og-hverdagen', 'q05', 'flervalg', 'Hva betyr «gemütlich»?', array['Kaldt', 'Rotete', 'Koselig', 'Stort']::text[], 2, 'Ordet brukes mye om hjem og kafeer.', true, true, 4),
  ('tysk-9:hjemmet-og-hverdagen', 'q06', 'flervalg', 'Hvordan sier du «Jeg dusjer»?', array['Ich dusche mich.', 'Ich bin duschen.', 'Ich dusche dich.', 'Mich dusche ich nicht.']::text[], 0, '«sich duschen» er et refleksivt verb.', true, true, 5),
  ('tysk-9:hjemmet-og-hverdagen', 'q07', 'flervalg', 'Hva betyr «Ich räume mein Zimmer auf»?', array['Jeg maler rommet mitt', 'Jeg forlater rommet mitt', 'Jeg liker rommet mitt', 'Jeg rydder rommet mitt']::text[], 3, '«aufräumen» betyr å rydde.', true, true, 6),
  ('tysk-9:hjemmet-og-hverdagen', 'q08', 'flervalg', 'Hva er «der Schreibtisch»?', array['Senga', 'Skrivebordet', 'Skapet', 'Stolen']::text[], 1, '«schreiben» betyr å skrive.', true, true, 7),
  ('tysk-9:hjemmet-og-hverdagen', 'q09', 'flervalg', 'Hvilket ord betyr «først»?', array['dann', 'danach', 'zuerst', 'später']::text[], 2, '«dann» betyr så, og «danach» betyr etterpå.', true, false, 8),
  ('tysk-9:hjemmet-og-hverdagen', 'q10', 'flervalg', 'Hva betyr «Ich sehe am Abend fern»?', array['Jeg ser langt om kvelden', 'Jeg går ut om kvelden', 'Jeg leser om kvelden', 'Jeg ser på TV om kvelden']::text[], 3, '«fernsehen» betyr å se på TV.', true, false, 9),
  ('tysk-9:hjemmet-og-hverdagen', 'm01', 'sant-usant', '«das Badezimmer» er badet.', array['Sant', 'Usant']::text[], 0, 'Det kalles ofte bare «das Bad».', false, true, 10),
  ('tysk-9:hjemmet-og-hverdagen', 'm02', 'sant-usant', '«aufstehen» er et delbart verb.', array['Sant', 'Usant']::text[], 0, '«Ich stehe früh auf.»', false, true, 11),
  ('tysk-9:hjemmet-og-hverdagen', 'm03', 'sant-usant', '«der Stuhl» betyr bordet.', array['Sant', 'Usant']::text[], 1, '«der Stuhl» er stolen. Bordet heter «der Tisch».', false, true, 12),
  ('tysk-9:hjemmet-og-hverdagen', 'm04', 'sant-usant', 'Setningen «Dann ich esse Frühstück» har riktig ordstilling.', array['Sant', 'Usant']::text[], 1, 'Verbet skal stå på andre plass: «Dann esse ich Frühstück».', false, true, 13),
  ('tysk-9:hjemmet-og-hverdagen', 'm05', 'flervalg', 'Hva betyr «Hausaufgaben machen»?', array['Å gjøre lekser', 'Å vaske huset', 'Å lage mat', 'Å bygge hus']::text[], 0, '«Hausaufgaben» betyr hjemmelekser.', false, true, 14),
  ('tysk-9:hjemmet-og-hverdagen', 'm06', 'flervalg', 'Hvilket rom sover du i?', array['die Küche', 'das Schlafzimmer', 'das Wohnzimmer', 'der Garten']::text[], 1, '«schlafen» betyr å sove.', false, true, 15),
  ('tysk-9:hjemmet-og-hverdagen', 'm07', 'flervalg', 'Hva betyr «danach»?', array['Før', 'Aldri', 'Etterpå', 'I dag']::text[], 2, 'Ordet brukes når du forteller hva som skjer etterpå.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('tysk-9:hjemmet-og-hverdagen', 15)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('tysk-9:byen-og-veibeskrivelse', 'tysk-9', 'byen-og-veibeskrivelse', 'Byen og veibeskrivelse', 'Steder i byen, hvordan du spør om og forstår en veibeskrivelse på tysk, zum og zur, transportmidler og lyttestrategier.', array[2, 1]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('tysk-9:byen-og-veibeskrivelse', '## I byen – in der Stadt
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('tysk-9:byen-og-veibeskrivelse', 'der Bahnhof', 'jernbanestasjonen', 0),
  ('tysk-9:byen-og-veibeskrivelse', 'die Bushaltestelle', 'bussholdeplassen', 1),
  ('tysk-9:byen-og-veibeskrivelse', 'die Apotheke', 'apoteket', 2),
  ('tysk-9:byen-og-veibeskrivelse', 'die Bibliothek', 'biblioteket', 3),
  ('tysk-9:byen-og-veibeskrivelse', 'das Rathaus', 'rådhuset', 4),
  ('tysk-9:byen-og-veibeskrivelse', 'die Ampel', 'trafikklyset', 5),
  ('tysk-9:byen-og-veibeskrivelse', 'die Kreuzung', 'krysset', 6),
  ('tysk-9:byen-og-veibeskrivelse', 'geradeaus', 'rett fram', 7),
  ('tysk-9:byen-og-veibeskrivelse', 'links / rechts', 'til venstre / til høyre', 8),
  ('tysk-9:byen-og-veibeskrivelse', 'Biegen Sie links ab.', 'Ta til venstre.', 9),
  ('tysk-9:byen-og-veibeskrivelse', 'gegenüber', 'overfor', 10),
  ('tysk-9:byen-og-veibeskrivelse', 'Wie komme ich zum …?', 'Hvordan kommer jeg til …?', 11),
  ('tysk-9:byen-og-veibeskrivelse', 'zum / zur', 'til (zu + dem / zu + der)', 12),
  ('tysk-9:byen-og-veibeskrivelse', 'zu Fuß', 'til fots', 13),
  ('tysk-9:byen-og-veibeskrivelse', 'mit der U-Bahn', 'med T-banen', 14),
  ('tysk-9:byen-og-veibeskrivelse', 'Können Sie das bitte wiederholen?', 'Kan De gjenta det?', 15);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('tysk-9:byen-og-veibeskrivelse', 'q01', 'flervalg', 'Hva er «der Bahnhof»?', array['Flyplassen', 'Bussholdeplassen', 'Havnen', 'Jernbanestasjonen']::text[], 3, '«die Bahn» betyr jernbanen.', true, true, 0),
  ('tysk-9:byen-og-veibeskrivelse', 'q02', 'flervalg', 'Hva betyr «geradeaus»?', array['Til venstre', 'Rett fram', 'Til høyre', 'Tilbake']::text[], 1, '«gerade» betyr rett.', true, true, 1),
  ('tysk-9:byen-og-veibeskrivelse', 'q03', 'flervalg', 'Hvordan spør du hvordan du kommer til museet?', array['Wo wohnst du?', 'Was kostet das Museum?', 'Wie komme ich zum Museum?', 'Ist das Museum schön?']::text[], 2, '«Wie komme ich zum …?» brukes når du spør om veien.', true, true, 2),
  ('tysk-9:byen-og-veibeskrivelse', 'q04', 'flervalg', 'Hva er «die Apotheke»?', array['Apoteket', 'Biblioteket', 'Banken', 'Postkontoret']::text[], 0, 'Biblioteket heter «die Bibliothek».', true, true, 3),
  ('tysk-9:byen-og-veibeskrivelse', 'q05', 'flervalg', 'Hvorfor heter det «zur Post», men «zum Bahnhof»?', array['Fordi Post er et sted', 'Fordi «Post» er hunkjønn og «Bahnhof» hankjønn', 'Fordi Bahnhof er større', 'Det er tilfeldig']::text[], 1, 'zu + der blir zur, og zu + dem blir zum.', true, true, 4),
  ('tysk-9:byen-og-veibeskrivelse', 'q06', 'flervalg', 'Hva betyr «Biegen Sie an der Ampel rechts ab»?', array['Gå rett fram forbi lyskrysset', 'Stopp ved lyskrysset', 'Snu ved lyskrysset', 'Ta til høyre ved lyskrysset']::text[], 3, '«abbiegen» betyr å svinge.', true, true, 5),
  ('tysk-9:byen-og-veibeskrivelse', 'q07', 'flervalg', 'Hva betyr «zu Fuß»?', array['Til fots', 'Med bil', 'Med sykkel', 'Med tog']::text[], 0, '«der Fuß» betyr foten.', true, true, 6),
  ('tysk-9:byen-og-veibeskrivelse', 'q08', 'flervalg', 'Hva betyr «gegenüber»?', array['Bak', 'Under', 'Overfor', 'Ved siden av']::text[], 2, 'Ved siden av heter «neben».', true, true, 7),
  ('tysk-9:byen-og-veibeskrivelse', 'q09', 'flervalg', 'Hva er en nyttig strategi hvis du ikke forstår en veibeskrivelse?', array['Å gå hjem', 'Å late som du forstår', 'Å snakke norsk', 'Å be om at det gjentas langsommere']::text[], 3, '«Können Sie das bitte wiederholen?»', true, false, 8),
  ('tysk-9:byen-og-veibeskrivelse', 'q10', 'flervalg', 'Hva er «das Rathaus»?', array['Et hus for rotter', 'Rådhuset', 'Et bibliotek', 'En restaurant']::text[], 1, '«der Rat» betyr rådet.', true, false, 9),
  ('tysk-9:byen-og-veibeskrivelse', 'm01', 'sant-usant', '«links» betyr venstre.', array['Sant', 'Usant']::text[], 0, 'Høyre heter «rechts».', false, true, 10),
  ('tysk-9:byen-og-veibeskrivelse', 'm02', 'sant-usant', '«die Bibliothek» er en bokhandel.', array['Sant', 'Usant']::text[], 1, '«die Bibliothek» er biblioteket. En bokhandel heter «die Buchhandlung».', false, true, 11),
  ('tysk-9:byen-og-veibeskrivelse', 'm03', 'sant-usant', '«mit dem Bus» betyr med bussen.', array['Sant', 'Usant']::text[], 0, 'Etter «mit» brukes dativ: dem Bus.', false, true, 12),
  ('tysk-9:byen-og-veibeskrivelse', 'm04', 'sant-usant', '«die Kreuzung» betyr kirken.', array['Sant', 'Usant']::text[], 1, '«die Kreuzung» betyr krysset. Kirken heter «die Kirche».', false, true, 13),
  ('tysk-9:byen-og-veibeskrivelse', 'm05', 'flervalg', 'Hvordan sier du «Er det langt?»?', array['Ist das weit?', 'Ist das hier?', 'Wo ist das?', 'Was ist das?']::text[], 0, '«weit» betyr langt unna.', false, true, 14),
  ('tysk-9:byen-og-veibeskrivelse', 'm06', 'flervalg', 'Hva er «die U-Bahn»?', array['Et fly', 'Undergrunnsbanen, T-banen', 'En båt', 'En buss']::text[], 1, 'U står for «Untergrund».', false, true, 15),
  ('tysk-9:byen-og-veibeskrivelse', 'm07', 'flervalg', 'Hva betyr «Nehmen Sie die zweite Straße links»?', array['Ta den første gata til høyre', 'Gå to kvartaler rett fram', 'Ta den andre gata til venstre', 'Kryss gata to ganger']::text[], 2, '«zweite» betyr andre.', false, true, 16);
