  ('spansk-vg2:litteratur', 'Federico García Lorca', 'Andalusisk dikter og dramatiker, drept i 1936', 0),
  ('spansk-vg2:litteratur', 'Romancero gitano', 'Diktsamling av Lorca (1928)', 1),
