  ('kinesisk-vg2:reise-og-veibeskrivelse', '高铁 gāotiě', 'høyhastighetstog', 4),
  ('kinesisk-vg2:reise-og-veibeskrivelse', '骑自行车 qí zìxíngchē', 'sykle', 5),
